{
  "name": "Cubitt B2B Sales Portal",
  "description": "A high-end corporate sales platform for Cubitt Panama, featuring a minimalist Apple-inspired interface for seamless bulk ordering and catalog management."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ProductVariant {
  sku: string;
  option1: string; // usually Color
  price: number;
  inventory: number;
  image: string;
}

export interface Product {
  id: string;
  handle: string;
  title: string;
  description: string;
  vendor: string;
  category: string;
  type: string;
  mainImage: string;
  variants: ProductVariant[];
  tags: string[];
}

export interface CartItem {
  product: Product;
  variant: ProductVariant;
  quantity: number;
}

export type Category = 'All' | 'Smartwatches' | 'Audio' | 'Básculas' | 'Accesorios';

export interface User {
  id: string;
  companyName: string;
  email: string;
  authorized: boolean;
}

import React, { useState, useMemo, useEffect } from 'react';
import { User, Product, CartItem, Category } from './types';
import { PRODUCTS } from './constants';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import ProductGrid from './components/ProductGrid';
import ProductModal from './components/ProductModal';
import CartSheet from './components/CartSheet';
import Login from './components/Login';
import CheckoutOverlay from './components/CheckoutOverlay';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  // Filter products based on category and search
  const filteredProducts = useMemo(() => {
    return PRODUCTS.filter(p => {
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.variants.some(v => v.sku.toLowerCase().includes(searchQuery.toLowerCase()));
      return matchesCategory && matchesSearch;
    });
  }, [selectedCategory, searchQuery]);

  const handleAddToCart = (product: Product, variantSku: string, quantity: number) => {
    const variant = product.variants.find(v => v.sku === variantSku)!;
    setCart(prev => {
      const existingIndex = prev.findIndex(item => item.variant.sku === variantSku);
      if (existingIndex > -1) {
        const newCart = [...prev];
        newCart[existingIndex].quantity += quantity;
        return newCart;
      }
      return [...prev, { product, variant, quantity }];
    });
  };

  const removeFromCart = (sku: string) => {
    setCart(prev => prev.filter(item => item.variant.sku !== sku));
  };

  const updateCartQuantity = (sku: string, qty: number) => {
    setCart(prev => prev.map(item => item.variant.sku === sku ? { ...item, quantity: Math.max(1, qty) } : item));
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  return (
    <div className="min-h-screen bg-[#fbfbfd] text-[#1d1d1f] flex flex-col">
      <Navbar 
        user={user} 
        cartCount={cart.reduce((acc, curr) => acc + curr.quantity, 0)}
        onOpenCart={() => setIsCartOpen(true)}
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      />

      <div className="flex flex-1 pt-16">
        <Sidebar 
          selectedCategory={selectedCategory} 
          setSelectedCategory={setSelectedCategory} 
        />

        <main className="flex-1 p-6 lg:p-10">
          <div className="max-w-7xl mx-auto">
            <header className="mb-10">
              <h1 className="text-4xl font-semibold tracking-tight mb-2">
                {selectedCategory === 'All' ? 'Product Catalog' : selectedCategory}
              </h1>
              <p className="text-[#86868b] text-lg font-normal">
                {filteredProducts.length} Premium items found for your corporate order.
              </p>
            </header>

            <ProductGrid 
              products={filteredProducts} 
              onSelect={setSelectedProduct} 
            />
          </div>
        </main>
      </div>

      {selectedProduct && (
        <ProductModal 
          product={selectedProduct} 
          onClose={() => setSelectedProduct(null)} 
          onAdd={handleAddToCart}
        />
      )}

      {isCartOpen && (
        <CartSheet 
          cart={cart} 
          onClose={() => setIsCartOpen(false)} 
          onRemove={removeFromCart}
          onUpdate={updateCartQuantity}
          onCheckout={() => {
            setIsCartOpen(false);
            setIsCheckoutOpen(true);
          }}
        />
      )}

      {isCheckoutOpen && (
        <CheckoutOverlay 
          cart={cart} 
          onClose={() => setIsCheckoutOpen(false)}
          onConfirm={() => {
            alert("Order Confirmed! Notifications sent to Sales via Email and WhatsApp.");
            setCart([]);
            setIsCheckoutOpen(false);
          }}
        />
      )}

      <footer className="py-12 bg-white border-t border-[#d2d2d7] text-center text-[#86868b] text-sm">
        <div className="max-w-7xl mx-auto px-6">
          <p className="mb-4">© 2024 Cubitt Panama. Exclusive Corporate Sales Portal.</p>
          <div className="flex justify-center gap-6">
            <button className="hover:text-[#1d1d1f]">Support</button>
            <button className="hover:text-[#1d1d1f]">Privacy Policy</button>
            <button className="hover:text-[#1d1d1f]">Terms of Service</button>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

