}

const Login: React.FC<LoginProps> = ({ onLogin }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulation: any corporate email works for this B2B demo
    if (email.includes('@')) {
      onLogin({
        id: 'user_1',
        companyName: 'Fitness Solutions Ltd.',
        email: email,
