  return (
    <div className="min-h-screen bg-[#f5f5f7] flex items-center justify-center p-6 selection:bg-[#0071e3]/20">
      <div className="w-full max-w-[440px] bg-white rounded-[40px] shadow-apple-card overflow-hidden">
        <div className="flex flex-col items-center pt-16 pb-8 px-10 text-center">
