import React from 'react';
import { Product, Category } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: Category;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect, selectedCategory }) => {
  // Group products by category
  const categories = selectedCategory === 'All' 
    ? Array.from(new Set(products.map(p => p.category)))
    : [selectedCategory];

  return (
    <div className="flex flex-col space-y-12 pb-24">
      {categories.map(cat => {
        const catProducts = products.filter(p => p.category === cat);
        if (catProducts.length === 0) return null;

        return (
          <section key={cat} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="border-b border-[#d2d2d7] pb-4 mb-6">
              <h2 className="text-2xl font-semibold tracking-tight text-black">{cat}</h2>
            </div>

            <div className="grid grid-cols-1 gap-2">
              {/* Table Header */}
