                      Select
                    </button>
                  </div>
                </div>
              ))}
            </div>
          </section>
        );
      })}

      {products.length === 0 && (
        <div className="py-32 text-center">
          <span className="material-symbols-outlined text-[48px] text-[#d2d2d7] mb-4">inventory_2</span>
          <p className="text-[#86868b] text-xl font-light">No items found matching your search.</p>
        </div>
