import React, { useState, useMemo } from 'react';
import { User, Product, CartItem, Category } from './types';
import { PRODUCTS } from './constants';
import Navbar from './components/Navbar';
import Sidebar from './components/Sidebar';
import ProductGrid from './components/ProductGrid';
import ProductModal from './components/ProductModal';
import CartSheet from './components/CartSheet';
import Login from './components/Login';
import CheckoutOverlay from './components/CheckoutOverlay';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<Category>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);

  const filteredProducts = useMemo(() => {
    return PRODUCTS.filter(p => {
      const matchesCategory = selectedCategory === 'All' || p.category === selectedCategory;
      const matchesSearch = p.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                           p.variants.some(v => v.sku.toLowerCase().includes(searchQuery.toLowerCase())) ||
                           p.description.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesCategory && matchesSearch;
    });
  }, [selectedCategory, searchQuery]);

  const handleAddToCart = (product: Product, variantSku: string, quantity: number) => {
    const variant = product.variants.find(v => v.sku === variantSku)!;
    setCart(prev => {
      const existingIndex = prev.findIndex(item => item.variant.sku === variantSku);
      if (existingIndex > -1) {
        const newCart = [...prev];
        newCart[existingIndex].quantity += quantity;
        return newCart;
      }
      return [...prev, { product, variant, quantity }];
    });
  };

  const removeFromCart = (sku: string) => {
    setCart(prev => prev.filter(item => item.variant.sku !== sku));
  };

  const updateCartQuantity = (sku: string, qty: number) => {
    setCart(prev => prev.map(item => item.variant.sku === sku ? { ...item, quantity: Math.max(1, qty) } : item));
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  return (
    <div className="min-h-screen bg-[#fbfbfd] text-[#1d1d1f] flex flex-col font-sans selection:bg-primary/10">
      <Navbar 
        user={user} 
        cartCount={cart.reduce((acc, curr) => acc + curr.quantity, 0)}
        onOpenCart={() => setIsCartOpen(true)}
        searchQuery={searchQuery}
        setSearchQuery={setSearchQuery}
      />

      <div className="flex flex-1 pt-16">
        <Sidebar 
          selectedCategory={selectedCategory} 
          setSelectedCategory={setSelectedCategory} 
        />

        <main className="flex-1 p-8 lg:p-16 overflow-x-hidden">
          <div className="max-w-5xl mx-auto">
            <header className="mb-16">
              <div className="flex items-center gap-2 text-[11px] font-bold text-[#86868b] uppercase tracking-[0.2em] mb-4">
                <span className="w-1 h-1 bg-primary rounded-full"></span>
                Partner Order System
              </div>
              <h1 className="text-[44px] md:text-[56px] font-bold tracking-tight mb-4 text-black leading-[1.1]">
                {selectedCategory === 'All' ? 'Full Catalog' : selectedCategory}
              </h1>
              <p className="text-[#86868b] text-[19px] md:text-[21px] font-normal leading-relaxed max-w-2xl">
                High-density order list for corporate procurement. Select items to view specifications and variants.
              </p>
            </header>

            <ProductGrid 
              products={filteredProducts} 
              onSelect={setSelectedProduct} 
              selectedCategory={selectedCategory}
            />
          </div>
        </main>
      </div>

      {selectedProduct && (
        <ProductModal 
          product={selectedProduct} 
          onClose={() => setSelectedProduct(null)} 
          onAdd={handleAddToCart}
        />
      )}

      {isCartOpen && (
        <CartSheet 
          cart={cart} 
          onClose={() => setIsCartOpen(false)} 
          onRemove={removeFromCart}
          onUpdate={updateCartQuantity}
          onCheckout={() => {
            setIsCartOpen(false);
            setIsCheckoutOpen(true);
          }}
        />
      )}

      {isCheckoutOpen && (
        <CheckoutOverlay 
          cart={cart} 
          onClose={() => setIsCheckoutOpen(false)}
          onConfirm={() => {
            alert("Order Confirmed! Your designated sales representative will contact you shortly.");
            setCart([]);
            setIsCheckoutOpen(false);
          }}
        />
      )}

      <footer className="py-24 bg-white border-t border-[#d2d2d7]/50 text-[#86868b]">
        <div className="max-w-5xl mx-auto px-8 grid grid-cols-1 md:grid-cols-2 gap-12">
          <div>
            <div className="flex items-center gap-3 font-semibold text-[19px] text-black mb-6">
              <svg className="w-6 h-6 text-black" fill="none" viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg">
                <path d="M44 11.2727C44 14.0109 39.8386 16.3957 33.69 17.6364C39.8386 18.877 44 21.2618 44 24C44 26.7382 39.8386 29.123 33.69 30.3636C39.8386 31.6043 44 33.9891 44 36.7273C44 40.7439 35.0457 44 24 44C12.9543 44 4 40.7439 4 36.7273C4 33.9891 8.16144 31.6043 14.31 30.3636C8.16144 29.123 4 26.7382 4 24C4 21.2618 8.16144 18.877 14.31 17.6364C8.16144 16.3957 4 14.0109 4 11.2727C4 7.25611 12.9543 4 24 4C35.0457 4 44 7.25611 44 11.2727Z" fill="currentColor"></path>
              </svg>
              Cubitt B2B Panama
            </div>
            <p className="text-[14px] max-w-sm leading-relaxed text-[#424245]">
              The standard for organizational health and connectivity in Panama. Exclusive portal for wholesale procurement.
            </p>
          </div>
          <div className="flex flex-col md:items-end justify-center">
            <p className="text-[12px] mb-4 font-medium">© 2024 Cubitt Panama. Authorized Partner Portal.</p>
            <div className="flex gap-8 text-[13px] font-medium text-[#424245]">
              <button className="hover:text-black transition-colors">Compliance</button>
              <button className="hover:text-black transition-colors">Privacy Policy</button>
              <button className="hover:text-black transition-colors">Sales Support</button>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

