import React from 'react';
import { Product } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: string;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect }) => {
  // Group products by 'Type' field from CSV
  const groupedProducts = products.reduce((acc, product) => {
    const type = product.type || 'Otros';
    if (!acc[type]) acc[type] = [];
    acc[type].push(product);
    return acc;
  }, {} as Record<string, Product[]>);

  return (
    <main className="flex-1 min-w-0 pb-20">
      <div className="mb-6 md:mb-10">
        <div className="flex items-center gap-2 text-[8px] md:text-[10px] font-black text-black uppercase tracking-[0.2em] mb-2 md:mb-4">
          <span className="w-1.5 h-1.5 bg-black rounded-full"></span>
          PORTAL MAYORISTA CUBITT
        </div>
        <h1 className="text-2xl md:text-4xl font-bold tracking-tighter text-black leading-none">
          Catálogo Técnico
        </h1>
      </div>

      <div className="space-y-10 md:space-y-16">
        {(Object.entries(groupedProducts) as [string, Product[]][]).map(([type, items]) => (
          <div key={type} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
            {/* Minimal Header */}
            <div className="flex items-center gap-3 mb-4">
              <h2 className="text-[12px] md:text-sm font-black text-[#86868B] uppercase tracking-widest">{type}</h2>
              <div className="h-px bg-black/5 flex-1" />
            </div>

            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6 gap-2 md:gap-4">
              {items.map(product => (
                <div 
                  key={product.id}
                  onClick={() => onSelect(product)}
                  className="group bg-white aspect-square rounded-xl md:rounded-[20px] p-3 md:p-5 border border-black/[0.03] hover:border-black/10 hover:shadow-xl transition-all cursor-pointer flex flex-col justify-between relative overflow-hidden"
                >
                  <div className="relative z-10">
                    <div className="flex flex-wrap gap-0.5 mb-1.5 md:mb-3">
                      {product.tags.slice(0, 1).map(tag => (
                        <span key={tag} className="text-[7px] md:text-[8px] font-black text-white bg-black/40 px-1 py-0.5 rounded uppercase leading-none">
                          {tag}
                        </span>
                      ))}
                    </div>
                    <h3 className="text-[11px] md:text-[14px] font-bold text-[#1D1D1F] leading-tight group-hover:text-black transition-colors">
                      {product.title}
                    </h3>
                    <div className="text-[9px] md:text-[10px] font-mono text-[#86868B] mt-1 uppercase opacity-60">
                      {product.variants[0].sku.split('-')[0]}
                    </div>
                  </div>

                  <div className="relative z-10 flex items-center justify-between mt-2">
                    <div className="text-[14px] md:text-[18px] font-black text-black">
                      ${product.variants[0].price.toFixed(2)}
                    </div>
                    <div className="w-6 h-6 md:w-8 md:h-8 rounded-full bg-[#F5F5F7] group-hover:bg-black group-hover:text-white flex items-center justify-center transition-all">
                      <span className="material-icons text-[12px] md:text-sm">chevron_right</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {products.length === 0 && (
        <div className="py-20 text-center">
          <span className="material-icons text-[32px] text-[#D1D1D6] mb-2">search_off</span>
          <p className="text-[#86868B] text-sm">No se encontraron productos.</p>
        </div>
      )}
    </main>
  );
};

export default ProductGrid;

import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = () => {
    let text = `*SOLICITUD DE PROFORMA - CUBITT PANAMÁ*\n\n`;
    text += `Lista de Artículos:\n`;
    cart.forEach((item, index) => {
      text += `${index + 1}. ${item.product.title} (${item.variant.option1})\n`;
      text += `   SKU: ${item.variant.sku} | Cant: ${item.quantity}\n`;
      text += `   Subtotal: $${(item.variant.price * item.quantity).toFixed(2)}\n\n`;
    });
    text += `*SUBTOTAL:* $${subtotal.toFixed(2)}\n`;
    text += `*ITBMS (7%):* $${tax.toFixed(2)}\n`;
    text += `*TOTAL ESTIMADO:* $${total.toFixed(2)}\n\n`;
    text += `_Favor contactarme para confirmar tiempos de entrega._`;
    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText());
    window.open(`https://wa.me/50766778899?text=${message}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = encodeURIComponent('Solicitud de Proforma Corporativa - Cubitt Panama');
    const body = encodeURIComponent(generateProformaText().replace(/\*/g, ''));
    window.location.href = `mailto:ventas@cubitt.com.pa?subject=${subject}&body=${body}`;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
        <span className="material-icons-outlined text-[48px] text-[#D1D1D6] mb-4">shopping_bag</span>
        <h2 className="text-xl font-bold mb-2">Tu pedido está vacío</h2>
        <button 
          onClick={onBack}
          className="text-sm bg-black text-white px-6 py-3 rounded-xl font-bold"
        >
          Ir al Catálogo
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 md:py-12 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between mb-6 md:mb-10">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] md:text-xs font-bold text-[#86868B] uppercase tracking-widest mb-2 hover:text-black">
            <span className="material-icons text-xs mr-1">arrow_back</span>
            Volver
          </button>
          <h1 className="text-2xl md:text-3xl font-bold text-black tracking-tight">Revisar Pedido</h1>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 md:gap-10">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-2xl md:rounded-[32px] shadow-sm border border-[#E5E5E5] overflow-hidden">
            <div className="p-4 md:p-8 border-b border-[#E5E5E5] flex justify-between items-center bg-white/50">
              <h2 className="text-sm md:text-lg font-bold text-black">Resumen ({cart.length})</h2>
              <span className="text-[9px] md:text-[11px] font-bold text-green-600 uppercase tracking-widest">En Stock</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead>
                  <tr className="bg-[#F5F5F7] text-[9px] md:text-[10px] uppercase tracking-widest font-black text-[#86868B] border-b border-[#E5E5E5]">
                    <th className="px-4 md:px-8 py-3 md:py-5">Producto</th>
                    <th className="px-2 md:px-6 py-3 md:py-5 text-center">Cant.</th>
                    <th className="px-4 md:px-8 py-3 md:py-5 text-right">Total</th>
                    <th className="px-2 py-3 md:py-5"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E5E5E5]">
                  {cart.map((item) => (
                    <tr key={item.variant.sku} className="hover:bg-[#F5F5F7]/30 transition-colors group">
                      <td className="px-4 md:px-8 py-4 md:py-7">
                        <div className="flex items-center gap-3 md:gap-5">
                          <div className="h-10 w-10 md:h-16 md:w-16 bg-[#F5F5F7] rounded-lg md:rounded-2xl flex items-center justify-center p-1 md:p-2 border border-black/5 shrink-0">
                            <img src={item.variant.image} className="h-full w-auto object-contain mix-blend-multiply" />
                          </div>
                          <div>
                            <div className="text-[12px] md:text-[16px] font-bold text-black leading-tight">{item.product.title}</div>
                            <div className="text-[9px] md:text-[11px] font-mono text-[#86868B] uppercase">{item.variant.option1}</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-2 md:px-6 py-4 md:py-7 text-center">
                        <div className="flex items-center justify-center border border-[#E5E5E5] rounded-lg bg-white h-8 md:h-11 w-20 md:w-28 mx-auto">
                          <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity - 5)} className="flex-1 text-gray-400 font-bold">-</button>
                          <span className="w-6 md:w-10 text-center text-[11px] md:text-[15px] font-bold text-black">{item.quantity}</span>
                          <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity + 5)} className="flex-1 text-gray-400 font-bold">+</button>
                        </div>
                      </td>
                      <td className="px-4 md:px-8 py-4 md:py-7 text-right text-[12px] md:text-[17px] font-bold text-black">${(item.variant.price * item.quantity).toFixed(2)}</td>
                      <td className="px-2 py-4 md:py-7 text-right">
                        <button onClick={() => onRemove(item.variant.sku)} className="p-1 text-gray-300 hover:text-red-500">
                          <span className="material-icons text-[16px] md:text-[20px]">delete_outline</span>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="lg:col-span-4">
          <div className="bg-white rounded-2xl md:rounded-[32px] shadow-lg border border-[#E5E5E5] p-6 md:p-10 sticky top-24">
            <h2 className="text-lg md:text-2xl font-bold text-black mb-6 md:mb-10">Total Orden</h2>
            <div className="space-y-3 md:space-y-5 mb-6 md:mb-10">
              <div className="flex justify-between text-sm md:text-[16px] text-[#86868B]">
                <span>Subtotal</span>
                <span className="font-bold text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm md:text-[16px] text-[#86868B]">
                <span>ITBMS (7%)</span>
                <span className="font-bold text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="h-px bg-[#E5E5E5] my-4 md:my-8" />
              <div className="flex justify-between items-end">
                <span className="text-sm md:text-xl font-bold text-black uppercase">Total</span>
                <div className="text-right">
                  <span className="text-2xl md:text-[40px] font-black text-black leading-none">${total.toFixed(2)}</span>
                  <span className="block text-[9px] md:text-[11px] text-[#86868B] font-black uppercase mt-1">USD</span>
                </div>
              </div>
            </div>

            <div className="space-y-3 pt-4">
              <button 
                onClick={handleWhatsApp}
                className="w-full h-12 md:h-16 bg-[#25D366] text-white rounded-xl md:rounded-2xl font-bold text-sm md:text-lg flex items-center justify-center gap-3 active:scale-95 transition-all shadow-md shadow-green-100"
              >
                <svg className="w-5 h-5 md:w-6 md:h-6 fill-current" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"></path></svg>
