import React, { useState } from 'react';
import { Product, ProductVariant } from '../types';

interface ProductDetailViewProps {
  product: Product;
  onAddToCart: (p: Product, variantSku: string, quantity: number) => void;
  onBack: () => void;
}

const ProductDetailView: React.FC<ProductDetailViewProps> = ({ product, onAddToCart, onBack }) => {
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(product.variants[0]);
  const [quantity, setQuantity] = useState(50);

  const getColorHex = (name: string) => {
    const n = name.toLowerCase();
    if (n.includes('obsidian') || n.includes('negra') || n.includes('black')) return '#1A1A1A';
    if (n.includes('white') || n.includes('blanca') || n.includes('off white')) return '#F8F8F8';
    if (n.includes('gray') || n.includes('gris') || n.includes('gun metal')) return '#636366';
    if (n.includes('blue') || n.includes('azul')) return '#004080';
    if (n.includes('rose gold')) return '#E6BE8A';
    if (n.includes('green') || n.includes('verde')) return '#2D5A27';
    if (n.includes('lilac') || n.includes('violeta')) return '#DCD0FF';
    if (n.includes('sand')) return '#C2B280';
    if (n.includes('terracotta')) return '#B35C44';
    if (n.includes('pink') || n.includes('rosada')) return '#FFC0CB';
    if (n.includes('mickey blue')) return '#005DAB';
    if (n.includes('minnie pink')) return '#E52D87';
    return '#E5E5E5';
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 md:py-10 animate-in fade-in duration-500">
      <nav className="flex items-center gap-2 text-[9px] md:text-xs font-bold text-[#86868B] uppercase tracking-widest mb-6 md:mb-10">
        <button onClick={onBack} className="hover:text-black">Catálogo</button>
        <span className="text-gray-300">/</span>
        <span className="text-black">{product.title}</span>
      </nav>

      <div className="lg:grid lg:grid-cols-2 lg:gap-x-12 xl:gap-x-20">
        {/* Main Display */}
        <div className="space-y-4">
          <div className="relative bg-white rounded-2xl md:rounded-[40px] p-6 md:p-10 shadow-sm border border-black/5 aspect-square flex items-center justify-center overflow-hidden">
            <img 
              alt={product.title} 
              className="object-contain max-h-full max-w-full mix-blend-multiply transition-all duration-700" 
              src={selectedVariant.image}
            />
          </div>
          <div className="grid grid-cols-5 gap-2">
             {product.variants.map((v, i) => (
               <button 
                key={i} 
                onClick={() => setSelectedVariant(v)}
                className={`aspect-square rounded-lg md:rounded-xl border-2 p-1.5 bg-white transition-all ${selectedVariant.sku === v.sku ? 'border-black scale-95' : 'border-transparent'}`}
               >
                 <img src={v.image} className="w-full h-full object-contain mix-blend-multiply" />
               </button>
             ))}
          </div>
        </div>

        {/* Info Area */}
        <div className="mt-8 lg:mt-0">
          <div className="mb-6 md:mb-10 pb-6 md:pb-10 border-b border-black/5">
            <h3 className="text-[9px] md:text-[11px] font-black tracking-[0.3em] text-[#86868B] uppercase mb-2 md:mb-4">{product.type}</h3>
            <h1 className="text-3xl md:text-5xl font-black tracking-tight text-black mb-3 md:mb-4 leading-none">{product.title}</h1>
            <div className="flex items-baseline gap-2">
              <span className="text-2xl md:text-[32px] font-black text-black tracking-tighter">${selectedVariant.price.toFixed(2)}</span>
              <span className="text-[10px] md:text-sm font-bold text-[#86868B] uppercase tracking-widest">/ Unidad B2B</span>
            </div>
          </div>

          <div className="space-y-8 md:space-y-12">
            <div>
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[11px] md:text-[13px] font-black text-black uppercase tracking-widest">Variante Color</h3>
                <span className="text-[10px] font-bold text-[#86868B] uppercase">{selectedVariant.option1}</span>
              </div>
              <div className="flex flex-wrap gap-2 md:gap-3">
                {product.variants.map((v) => (
                  <button 
                    key={v.sku}
                    onClick={() => setSelectedVariant(v)}
                    className={`relative w-8 h-8 md:w-10 md:h-10 rounded-full border-2 md:border-4 transition-all duration-300 p-0.5 ${selectedVariant.sku === v.sku ? 'border-black scale-110 shadow-lg' : 'border-transparent hover:scale-105'}`}
                  >
                    <div 
                      className="w-full h-full rounded-full border border-black/5" 
                      style={{ backgroundColor: getColorHex(v.option1) }}
                    />
                  </button>
                ))}
              </div>
            </div>

            <div>
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[11px] md:text-[13px] font-black text-black uppercase tracking-widest">Cantidad del Pedido</h3>
                <span className="text-[9px] font-black text-[#86868B] uppercase bg-[#F5F5F7] px-2 py-0.5 rounded-full">Min: 5</span>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex items-center border border-black/5 rounded-xl md:rounded-2xl w-32 md:w-40 h-10 md:h-14 bg-[#F5F5F7] p-1">
                  <button onClick={() => setQuantity(q => Math.max(5, q - 5))} className="flex-1 h-full flex items-center justify-center text-gray-500 hover:text-black">
                    <span className="material-icons text-sm md:text-base">remove</span>
                  </button>
                  <input className="w-8 md:w-12 text-center bg-transparent border-none focus:ring-0 text-black font-black text-sm md:text-lg" value={quantity} readOnly />
                  <button onClick={() => setQuantity(q => q + 5)} className="flex-1 h-full flex items-center justify-center text-gray-500 hover:text-black">
                    <span className="material-icons text-sm md:text-base">add</span>
                  </button>
                </div>
                <div className="text-[9px] md:text-[11px] font-mono text-[#86868B] uppercase">SKU: {selectedVariant.sku}</div>
              </div>
            </div>
          </div>

          <button 
            onClick={() => onAddToCart(product, selectedVariant.sku, quantity)}
            className="w-full mt-10 bg-black hover:bg-[#1D1D1F] text-white font-black h-14 md:h-16 rounded-xl md:rounded-2xl shadow-xl transition-all duration-300 flex items-center justify-center gap-3 text-sm md:text-lg uppercase tracking-widest"
          >
            Añadir al Pedido
          </button>
        </div>
      </div>
    </div>
  );
};

