import React from 'react';
import { Product } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: string;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect }) => {
  // Sort products logically by Type then Title for a clean flow
  const sortedProducts = [...products].sort((a, b) => {
    if (a.type !== b.type) return a.type.localeCompare(b.type);
    return a.title.localeCompare(b.title);
  });

  return (
    <main className="flex-1 min-w-0">
      <div className="mb-6 md:mb-10">
        <div className="flex items-center gap-1.5 text-[8px] md:text-[10px] font-black text-black uppercase tracking-[0.2em] mb-2">
          <span className="w-1 md:w-1.5 h-1 md:h-1.5 bg-black rounded-full"></span>
          CUBITT B2B INVENTORY
        </div>
        <h1 className="text-xl md:text-3xl font-black tracking-tighter text-black leading-none uppercase">
          {sortedProducts.length} Artículos Disponibles
        </h1>
      </div>

      {/* Grid of Square Cards - Optimized for Mobile (2 columns) and High Density (up to 6 columns) */}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-2 md:gap-4">
        {sortedProducts.map(product => (
          <div 
            key={product.id}
            onClick={() => onSelect(product)}
            className="group bg-white aspect-square rounded-lg md:rounded-2xl p-3 md:p-5 border border-black/[0.04] hover:border-black/10 hover:shadow-lg transition-all cursor-pointer flex flex-col justify-between relative overflow-hidden"
          >
            {/* Type Badge - Very small */}
            <div className="relative z-10 flex justify-between items-start">
              <span className="text-[7px] md:text-[9px] font-black text-[#86868B] uppercase tracking-widest bg-[#F5F5F7] px-1.5 py-0.5 rounded">
                {product.type}
              </span>
              <span className="material-icons text-[10px] md:text-xs text-[#D1D1D6] group-hover:text-black">open_in_full</span>
            </div>

            <div className="relative z-10">
              <h3 className="text-[10px] md:text-[14px] font-bold text-[#1D1D1F] leading-tight group-hover:text-black transition-colors line-clamp-2 mb-1">
                {product.title}
              </h3>
              <div className="text-[8px] md:text-[10px] font-mono text-[#86868B] uppercase opacity-50">
                {product.variants[0].sku.split('-')[0]}
              </div>
            </div>

            <div className="relative z-10 flex items-center justify-between">
              <div className="text-[12px] md:text-[18px] font-black text-black leading-none">
                ${product.variants[0].price.toFixed(2)}
              </div>
              <div className="w-5 h-5 md:w-8 md:h-8 rounded-full bg-[#F5F5F7] group-hover:bg-black group-hover:text-white flex items-center justify-center transition-all">
                <span className="material-icons text-[10px] md:text-sm">add</span>
              </div>
            </div>

            {/* Visual indicator of multiple variants if applicable */}
            {product.variants.length > 1 && (
              <div className="absolute top-2 right-2 flex gap-0.5">
                <div className="w-1 h-1 rounded-full bg-black/10"></div>
                <div className="w-1 h-1 rounded-full bg-black/10"></div>
              </div>
            )}
          </div>
        ))}
      </div>

      {sortedProducts.length === 0 && (
        <div className="py-24 text-center">
          <span className="material-icons text-[32px] text-[#D1D1D6] mb-3">manage_search</span>
          <p className="text-[#86868B] text-sm font-bold uppercase tracking-widest">Sin resultados</p>
        </div>
      )}
    </main>
  );
};

