import React, { useState } from 'react';
import { Product, ProductVariant } from '../types';

interface ProductDetailViewProps {
  product: Product;
  onAddToCart: (p: Product, variantSku: string, quantity: number) => void;
  onBack: () => void;
}

const ProductDetailView: React.FC<ProductDetailViewProps> = ({ product, onAddToCart, onBack }) => {
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(product.variants[0]);
  const [quantity, setQuantity] = useState(50);

  const getColorHex = (name: string) => {
    const n = name.toLowerCase();
    if (n.includes('black') || n.includes('negra') || n.includes('obsidian')) return '#1A1A1A';
    if (n.includes('white') || n.includes('blanca')) return '#FFFFFF';
    if (n.includes('gray') || n.includes('gris')) return '#636366';
    if (n.includes('blue') || n.includes('azul')) return '#004080';
    if (n.includes('rose gold')) return '#E6BE8A';
    if (n.includes('green') || n.includes('verde')) return '#2D5A27';
    if (n.includes('purple') || n.includes('púrpura')) return '#800080';
    if (n.includes('pink') || n.includes('rosada')) return '#FFC0CB';
    if (n.includes('red') || n.includes('roja')) return '#FF0000';
    if (n.includes('beige') || n.includes('sand')) return '#F5F5DC';
    if (n.includes('orange') || n.includes('naranja')) return '#FFA500';
    if (n.includes('teal')) return '#008080';
    if (n.includes('lavender')) return '#E6E6FA';
    if (n.includes('lilac')) return '#C8A2C8';
    if (n.includes('mickey blue')) return '#005DAB';
    if (n.includes('minnie pink')) return '#E52D87';
    if (n.includes('chase blue')) return '#005CB9';
    if (n.includes('skye pink')) return '#F171B1';
    return '#E5E5E5';
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-4 md:py-8 animate-in fade-in duration-500">
      <nav className="mb-4">
        <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.2em] hover:text-black">
          <span className="material-icons text-xs mr-1">arrow_back</span> Atrás al Catálogo
        </button>
      </nav>

      <div className="flex flex-col md:grid md:grid-cols-2 gap-6 lg:gap-12">
        {/* Gallery / Product Image */}
        <div className="space-y-4">
          <div className="bg-white rounded-2xl md:rounded-[32px] p-6 border border-black/[0.04] aspect-square flex items-center justify-center overflow-hidden shadow-sm">
            <img 
              alt={product.title} 
              className="object-contain max-h-[70%] md:max-h-[85%] mix-blend-multiply transition-all duration-500" 
              src={selectedVariant.image}
            />
          </div>

          {/* Thumbnails if many variants */}
          {product.variants.length > 1 && (
            <div className="grid grid-cols-6 gap-2">
              {product.variants.slice(0, 12).map((v) => (
                <button 
                  key={v.sku}
                  onClick={() => setSelectedVariant(v)}
                  className={`aspect-square rounded-lg border-2 p-1 bg-white transition-all ${selectedVariant.sku === v.sku ? 'border-black' : 'border-transparent'}`}
                >
                  <img src={v.image} className="w-full h-full object-contain mix-blend-multiply" />
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Product Details */}
        <div className="flex flex-col">
          <div className="mb-6 pb-6 border-b border-black/5">
            <h3 className="text-[9px] md:text-[11px] font-black text-[#86868B] uppercase tracking-[0.3em] mb-1">{product.type}</h3>
            <h1 className="text-xl md:text-3xl font-black text-black tracking-tight leading-none mb-4">{product.title}</h1>
            <div className="flex items-baseline gap-2">
              <span className="text-xl md:text-3xl font-black text-black tracking-tighter">${selectedVariant.price.toFixed(2)}</span>
              <span className="text-[9px] md:text-[11px] font-bold text-[#86868B] uppercase tracking-widest">Unidad B2B</span>
            </div>
          </div>

          <div className="space-y-6">
            {/* Variant Selector - High Density Grid */}
            {product.variants.length > 1 && (
              <div>
                <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-3 flex justify-between">
                  <span>Seleccionar Color</span>
                  <span className="text-[#86868B]">{selectedVariant.option1}</span>
                </h3>
                <div className="grid grid-cols-6 sm:grid-cols-8 md:grid-cols-6 gap-2 md:gap-3">
                  {product.variants.map((v) => (
                    <button 
                      key={v.sku}
                      onClick={() => setSelectedVariant(v)}
                      title={v.option1}
                      className={`group relative aspect-square rounded-full border-2 transition-all p-0.5 ${selectedVariant.sku === v.sku ? 'border-black scale-110' : 'border-transparent hover:border-gray-200'}`}
                    >
                      <div 
                        className="w-full h-full rounded-full border border-black/5" 
                        style={{ backgroundColor: getColorHex(v.option1) }}
                      />
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Quantity Selector */}
            <div>
              <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-3">Cantidad (Múltiplos de 5)</h3>
              <div className="flex items-center gap-4">
                <div className="flex items-center border border-black/5 rounded-xl w-32 md:w-40 h-10 md:h-12 bg-[#F5F5F7] p-1 shadow-inner">
                  <button onClick={() => setQuantity(q => Math.max(5, q - 5))} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black transition-colors">
                    <span className="material-icons text-base">remove</span>
                  </button>
                  <input className="w-8 md:w-12 text-center bg-transparent border-none focus:ring-0 text-black font-black text-sm md:text-lg" value={quantity} readOnly />
                  <button onClick={() => setQuantity(q => q + 5)} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black transition-colors">
                    <span className="material-icons text-base">add</span>
                  </button>
                </div>
                <div className="text-[8px] md:text-[10px] font-mono text-[#86868B] uppercase">SKU: {selectedVariant.sku}</div>
              </div>
            </div>

            <button 
              onClick={() => onAddToCart(product, selectedVariant.sku, quantity)}
              className="w-full mt-auto bg-black hover:bg-[#1D1D1F] text-white font-black h-12 md:h-16 rounded-xl md:rounded-2xl shadow-xl transition-all active:scale-[0.98] uppercase text-[12px] md:text-[15px] tracking-[0.2em]"
            >
              Añadir al Pedido
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

