    if (n.includes('blue') || n.includes('azul') || n.includes('ocean')) return '#004080';
    if (n.includes('rose gold')) return '#E6BE8A';
    if (n.includes('green') || n.includes('verde') || n.includes('pine') || n.includes('sage')) return '#2D5A27';
