        <div className="flex flex-col">
          <div className="mb-6 pb-6 border-b border-black/5">
            <h3 className="text-[9px] md:text-[11px] font-black text-[#86868B] uppercase tracking-[0.3em] mb-1">{product.type}</h3>
            <h1 className="text-xl md:text-3xl font-black text-black tracking-tight leading-none mb-4">{product.title}</h1>
            <div className="flex items-baseline gap-2">
              <span className="text-xl md:text-3xl font-black text-black tracking-tighter">${selectedVariant.price.toFixed(2)}</span>
              <span className="text-[9px] md:text-[11px] font-bold text-[#86868B] uppercase tracking-widest">Unidad B2B</span>
            </div>
          </div>

          <div className="space-y-6">
            {product.variants.length > 1 && (
              <div>
                <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-3 flex justify-between">
                  <span>Seleccionar Color</span>
                  <span className="text-[#86868B]">{selectedVariant.option1}</span>
                </h3>
                <div className="grid grid-cols-6 sm:grid-cols-8 md:grid-cols-6 lg:grid-cols-7 gap-2 md:gap-3">
                  {product.variants.map((v) => (
                    <button 
                      key={v.sku}
                      onClick={() => setSelectedVariant(v)}
                      title={v.option1}
                      className={`group relative aspect-square rounded-full border-2 transition-all p-0.5 ${selectedVariant.sku === v.sku ? 'border-black scale-110' : 'border-transparent hover:border-gray-200'}`}
                    >
                      <div 
                        className="w-full h-full rounded-full border border-black/5" 
                        style={{ backgroundColor: getColorHex(v.option1) }}
                      />
                    </button>
                  ))}
                </div>
              </div>
            )}

            <div>
              <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-3">Cantidad de Artículos</h3>
              <div className="flex items-center gap-4">
                <div className="flex items-center border border-black/5 rounded-xl w-32 md:w-40 h-10 md:h-12 bg-[#F5F5F7] p-1 shadow-inner">
                  <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black transition-colors">
                    <span className="material-icons text-base">remove</span>
                  </button>
                  <input 
                    className="w-8 md:w-12 text-center bg-transparent border-none focus:ring-0 text-black font-black text-sm md:text-lg" 
                    value={quantity} 
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                  />
                  <button onClick={() => setQuantity(q => q + 1)} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black transition-colors">
                    <span className="material-icons text-base">add</span>
                  </button>
                </div>
                <div className="text-[8px] md:text-[10px] font-mono text-[#86868B] uppercase">SKU: {selectedVariant.sku}</div>
              </div>
            </div>

            <button 
              onClick={handleAdd}
              disabled={isAdded}
              className={`w-full mt-auto text-white font-black h-12 md:h-16 rounded-xl md:rounded-2xl shadow-xl transition-all active:scale-[0.98] uppercase text-[12px] md:text-[15px] tracking-[0.2em] flex items-center justify-center gap-2 ${isAdded ? 'bg-green-600' : 'bg-black hover:bg-[#1D1D1F]'}`}
            >
              <span className="material-icons text-sm md:text-lg">{isAdded ? 'check_circle' : 'shopping_bag'}</span>
              {isAdded ? 'Añadido al Pedido' : 'Añadir al Pedido'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetailView;

import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = (isEmail = false) => {
    const divider = isEmail ? "%0D%0A" : "\n";
    let text = `SOLICITUD DE PROFORMA - CUBITT PANAMÁ${divider}${divider}`;
    text += `Artículos Solicitados:${divider}`;
    cart.forEach((item, index) => {
      text += `${index + 1}. ${item.product.title} (${item.variant.option1})${divider}`;
      text += `   SKU: ${item.variant.sku} | Cantidad: ${item.quantity}${divider}`;
      text += `   Precio: $${(item.variant.price * item.quantity).toFixed(2)}${divider}${divider}`;
    });
    text += `--------------------------${divider}`;
    text += `SUBTOTAL: $${subtotal.toFixed(2)}${divider}`;
    text += `ITBMS (7%): $${tax.toFixed(2)}${divider}`;
    text += `TOTAL ESTIMADO: $${total.toFixed(2)}${divider}${divider}`;
    text += `Favor contactar para formalizar orden.`;
    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText(false));
    window.open(`https://wa.me/50766778899?text=${message}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = "Solicitud de Proforma B2B Cubitt Panama";
    const body = generateProformaText(true);
    const mailtoUrl = `mailto:ventas@cubitt.com.pa?subject=${encodeURIComponent(subject)}&body=${body}`;

    // Abrimos el link en una ventana nueva para forzar al sistema operativo a reconocer el protocolo mailto
    const win = window.open(mailtoUrl, '_blank');
    if (win) {
      setTimeout(() => win.close(), 100);
    }
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
        <span className="material-icons-outlined text-[48px] text-[#D1D1D6] mb-4">shopping_bag</span>
        <h2 className="text-lg font-black uppercase tracking-widest mb-4">Tu pedido está vacío</h2>
        <button onClick={onBack} className="text-[11px] font-black uppercase tracking-widest bg-black text-white px-8 py-3.5 rounded-full">Ir al Catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 md:py-10 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex items-center justify-between mb-6">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.2em] mb-2 hover:text-black">
            <span className="material-icons text-xs mr-1">arrow_back</span> Volver
          </button>
          <h1 className="text-2xl md:text-3xl font-black text-black tracking-tighter uppercase">Revisar Pedido</h1>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-xl md:rounded-3xl border border-[#E5E5E5] overflow-hidden shadow-sm">
