import React, { useState } from 'react';
import { Product, ProductVariant } from '../types';

interface ProductDetailViewProps {
  product: Product;
  onAddToCart: (p: Product, variantSku: string, quantity: number) => void;
  onBack: () => void;
}

const ProductDetailView: React.FC<ProductDetailViewProps> = ({ product, onAddToCart, onBack }) => {
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(product.variants[0]);
  const [quantity, setQuantity] = useState(1);
  const [isAdded, setIsAdded] = useState(false);

  const getColorHex = (name: string) => {
    const n = name.toLowerCase();
    if (n.includes('black') || n.includes('negra') || n.includes('obsidian') || n.includes('meteorite')) return '#1A1A1A';
    if (n.includes('white') || n.includes('blanca') || n.includes('arctic')) return '#FFFFFF';
    if (n.includes('gray') || n.includes('gris') || n.includes('steel') || n.includes('wolf')) return '#636366';
    if (n.includes('blue') || n.includes('azul') || n.includes('ocean') || n.includes('navy')) return '#004080';
    if (n.includes('rose gold')) return '#E6BE8A';
    if (n.includes('green') || n.includes('verde') || n.includes('forest') || n.includes('pine')) return '#2D5A27';
    if (n.includes('purple') || n.includes('royal')) return '#800080';
    if (n.includes('pink') || n.includes('rosada') || n.includes('flamingo')) return '#FFC0CB';
    if (n.includes('red') || n.includes('lava')) return '#FF0000';
    if (n.includes('sand') || n.includes('desert') || n.includes('mocha')) return '#C2B280';
    if (n.includes('teal')) return '#008080';
    if (n.includes('lavender')) return '#E6E6FA';
    if (n.includes('lilac')) return '#C8A2C8';
    if (n.includes('terracotta')) return '#B35C44';
    return '#E5E5E5';
  };

  const handleAdd = () => {
    onAddToCart(product, selectedVariant.sku, quantity);
    setIsAdded(true);
    setTimeout(() => setIsAdded(false), 2000);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-4 md:py-8 animate-in fade-in duration-500">
      <nav className="mb-4">
        <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.2em] hover:text-black transition-colors">
          <span className="material-icons text-xs mr-1">arrow_back</span> Catálogo
        </button>
      </nav>

      <div className="flex flex-col md:grid md:grid-cols-2 gap-6 lg:gap-12">
        {/* Imagen Principal - Cambio dinámico sin rejilla de miniaturas */}
        <div className="relative">
          <div className="bg-white rounded-2xl md:rounded-[32px] p-8 border border-black/[0.04] aspect-square flex items-center justify-center overflow-hidden shadow-sm">
            <img 
              key={selectedVariant.sku}
              alt={product.title} 
              className="object-contain max-h-[85%] mix-blend-multiply animate-in fade-in zoom-in-95 duration-500" 
              src={selectedVariant.image}
            />
          </div>
          {/* Badge de Stock */}
          <div className="absolute top-4 left-4">
            <span className="text-[9px] font-black bg-black text-white px-2.5 py-1 rounded-full uppercase tracking-widest shadow-lg">
              Stock: {selectedVariant.inventory}
            </span>
          </div>
        </div>

        {/* Detalles e Interacción */}
        <div className="flex flex-col">
          <div className="mb-6 pb-6 border-b border-black/5">
            <h3 className="text-[9px] md:text-[11px] font-black text-[#86868B] uppercase tracking-[0.3em] mb-1">{product.type}</h3>
            <h1 className="text-xl md:text-3xl font-black text-black tracking-tight leading-none mb-4">{product.title}</h1>
            <div className="flex items-baseline gap-2">
              <span className="text-xl md:text-3xl font-black text-black tracking-tighter">${selectedVariant.price.toFixed(2)}</span>
              <span className="text-[10px] md:text-[11px] font-bold text-[#86868B] uppercase tracking-widest">Unidad B2B</span>
            </div>
          </div>

          <div className="space-y-6">
            {/* Selector de Color - Burbujas limpias */}
            {product.variants.length > 1 && (
              <div>
                <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-3 flex justify-between">
                  <span>Seleccionar Color</span>
                  <span className="text-[#86868B]">{selectedVariant.option1}</span>
                </h3>
                <div className="flex flex-wrap gap-3">
                  {product.variants.map((v) => (
                    <button 
                      key={v.sku}
                      onClick={() => setSelectedVariant(v)}
                      title={v.option1}
                      className={`w-9 h-9 md:w-11 md:h-11 rounded-full border-2 transition-all p-0.5 ${selectedVariant.sku === v.sku ? 'border-black scale-110 shadow-md' : 'border-transparent hover:border-gray-200'}`}
                    >
                      <div 
                        className="w-full h-full rounded-full border border-black/5" 
                        style={{ backgroundColor: getColorHex(v.option1) }}
                      />
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Cantidad 1 a 1 */}
            <div>
              <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-3">Cantidad</h3>
              <div className="flex items-center gap-4">
                <div className="flex items-center border border-black/5 rounded-xl w-32 md:w-40 h-11 md:h-13 bg-[#F5F5F7] p-1 shadow-inner">
                  <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black">
                    <span className="material-icons text-base">remove</span>
                  </button>
                  <input 
                    className="w-8 md:w-12 text-center bg-transparent border-none focus:ring-0 text-black font-black text-sm md:text-lg" 
                    value={quantity} 
                    type="number"
                    min="1"
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                  />
                  <button onClick={() => setQuantity(q => q + 1)} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black">
                    <span className="material-icons text-base">add</span>
                  </button>
                </div>
                <div className="text-[8px] md:text-[10px] font-mono text-[#86868B] uppercase">SKU: {selectedVariant.sku}</div>
              </div>
            </div>

            {/* Botón de Acción con Feedback */}
            <button 
              onClick={handleAdd}
              className={`w-full mt-auto h-12 md:h-16 rounded-xl md:rounded-2xl shadow-xl transition-all active:scale-[0.98] uppercase text-[12px] md:text-[15px] tracking-[0.2em] flex items-center justify-center gap-2 font-black ${isAdded ? 'bg-green-600 text-white' : 'bg-black text-white hover:bg-[#1D1D1F]'}`}
            >
              <span className="material-icons text-sm md:text-lg">{isAdded ? 'check_circle' : 'add_shopping_cart'}</span>
              {isAdded ? 'Añadido' : 'Añadir al Pedido'}
            </button>
            <p className="text-[9px] text-center text-[#86868B] font-bold uppercase tracking-widest">
              Continúe navegando para añadir más productos.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetailView;

import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = (isEmail = false) => {
    const divider = isEmail ? "%0D%0A" : "\n";
    let text = `SOLICITUD DE PROFORMA - CUBITT PANAMÁ${divider}${divider}`;
    text += `Lista de Artículos Solicitados:${divider}`;
    text += `----------------------------------${divider}`;
    cart.forEach((item, index) => {
      text += `${index + 1}. ${item.product.title} (${item.variant.option1})${divider}`;
      text += `   SKU: ${item.variant.sku} | Cant: ${item.quantity}${divider}`;
      text += `   Subtotal: $${(item.variant.price * item.quantity).toFixed(2)}${divider}${divider}`;
    });
    text += `----------------------------------${divider}`;
    text += `SUBTOTAL: $${subtotal.toFixed(2)}${divider}`;
    text += `ITBMS (7%): $${tax.toFixed(2)}${divider}`;
    text += `TOTAL ESTIMADO: $${total.toFixed(2)}${divider}${divider}`;
    text += `Favor contactar al cliente para formalizar orden comercial.`;
    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText(false));
    window.open(`https://wa.me/50766778899?text=${message}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = "Solicitud de Proforma B2B - Cubitt Panama";
    const body = generateProformaText(true);
    // Protocolo Mailto optimizado para clientes móviles
    const mailtoUrl = `mailto:ventas@cubitt.com.pa?subject=${encodeURIComponent(subject)}&body=${body}`;
    window.location.href = mailtoUrl;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-20 text-center">
        <span className="material-icons-outlined text-[48px] text-[#D1D1D6] mb-4">shopping_bag</span>
        <h2 className="text-lg font-black uppercase tracking-widest mb-4">Pedido Vacío</h2>
        <button onClick={onBack} className="text-[11px] font-black uppercase tracking-widest bg-black text-white px-8 py-3.5 rounded-full">Ir al Catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4 md:py-10 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex items-center justify-between mb-6">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.2em] mb-2 hover:text-black">
            <span className="material-icons text-xs mr-1">arrow_back</span> Volver
          </button>
          <h1 className="text-2xl md:text-3xl font-black text-black tracking-tighter uppercase">Revisar Pedido</h1>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-xl md:rounded-3xl border border-[#E5E5E5] overflow-hidden shadow-sm">
            <div className="p-4 md:p-6 border-b border-[#E5E5E5] flex justify-between items-center bg-[#F5F5F7]/30">
              <h2 className="text-[11px] md:text-sm font-black text-black uppercase tracking-widest">Resumen de Artículos ({cart.length})</h2>
              <span className="text-[9px] font-black text-green-600 uppercase tracking-widest px-2 py-1 bg-green-50 rounded">Listado B2B</span>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[500px]">
                <thead>
                  <tr className="bg-[#F5F5F7] text-[9px] font-black text-[#86868B] uppercase tracking-widest border-b border-[#E5E5E5]">
                    <th className="px-4 md:px-6 py-4">Producto</th>
                    <th className="px-4 py-4 text-center">Cant.</th>
                    <th className="px-4 md:px-6 py-4 text-right">Subtotal</th>
                    <th className="px-4 py-4 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[#E5E5E5]">
                  {cart.map((item) => (
                    <tr key={item.variant.sku} className="hover:bg-[#F5F5F7]/30 transition-colors group">
                      <td className="px-4 md:px-6 py-4">
                        <div className="flex items-center gap-3">
                          <div className="h-10 w-10 md:h-12 md:w-12 bg-[#F5F5F7] rounded-lg p-1 border border-black/5 shrink-0">
                            <img src={item.variant.image} className="h-full w-full object-contain mix-blend-multiply" />
                          </div>
                          <div>
                            <div className="text-[11px] md:text-[13px] font-bold text-black leading-none mb-1">{item.product.title}</div>
                            <div className="text-[9px] font-mono text-[#86868B] uppercase">{item.variant.option1}</div>
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-4">
                        <div className="flex items-center justify-center border border-[#E5E5E5] rounded-full bg-white h-8 w-24 mx-auto overflow-hidden">
                          <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity - 1)} className="w-8 text-gray-400 font-bold hover:text-black">-</button>
                          <span className="flex-1 text-center text-[11px] font-black text-black">{item.quantity}</span>
                          <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity + 1)} className="w-8 text-gray-400 font-bold hover:text-black">+</button>
                        </div>
                      </td>
                      <td className="px-4 md:px-6 py-4 text-right text-[12px] md:text-[15px] font-black text-black">
                        ${(item.variant.price * item.quantity).toFixed(2)}
                      </td>
                      <td className="px-4 py-4">
                        <button onClick={() => onRemove(item.variant.sku)} className="text-gray-300 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity">
                          <span className="material-icons text-lg">close</span>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="lg:col-span-4">
          <div className="bg-white rounded-xl md:rounded-3xl border border-[#E5E5E5] p-6 md:p-8 sticky top-24 shadow-md">
            <h2 className="text-[11px] font-black text-black uppercase tracking-[0.2em] mb-6">Totales de Orden</h2>
            <div className="space-y-4 mb-8">
              <div className="flex justify-between text-[12px] md:text-[13px] text-[#86868B] font-bold uppercase tracking-widest">
                <span>Subtotal</span>
                <span className="text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-[12px] md:text-[13px] text-[#86868B] font-bold uppercase tracking-widest">
                <span>ITBMS (7%)</span>
                <span className="text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="h-px bg-[#E5E5E5] my-4" />
              <div className="flex justify-between items-end">
                <span className="text-[10px] font-black text-black uppercase tracking-[0.3em]">Total Final</span>
                <div className="text-right leading-none">
                  <span className="text-2xl md:text-4xl font-black text-black tracking-tighter">${total.toFixed(2)}</span>
                  <span className="block text-[8px] font-black text-[#86868B] uppercase mt-1">USD Dólares</span>
                </div>
              </div>
            </div>

            <div className="space-y-2">
              <button 
                onClick={handleWhatsApp}
                className="w-full h-12 md:h-14 bg-[#25D366] text-white rounded-xl font-black text-[11px] md:text-[13px] uppercase tracking-widest flex items-center justify-center gap-2 hover:brightness-105 active:scale-95 transition-all shadow-lg shadow-green-100"
              >
                <svg className="w-4 h-4 md:w-5 md:h-5 fill-current" viewBox="0 0 24 24"><path d="M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z"></path></svg>
                WhatsApp Proforma
              </button>
              <button 
                onClick={handleEmail}
                className="w-full h-12 md:h-14 border border-black text-black bg-white rounded-xl font-black text-[11px] md:text-[13px] uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-gray-50 active:scale-95 transition-all"
