import React, { useState } from 'react';
import { Product, ProductVariant } from '../types';

interface ProductDetailViewProps {
  product: Product;
  onAddToCart: (p: Product, variantSku: string, quantity: number) => void;
  onBack: () => void;
}

const ProductDetailView: React.FC<ProductDetailViewProps> = ({ product, onAddToCart, onBack }) => {
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(product.variants[0]);
  const [quantity, setQuantity] = useState(1);
  const [isAdded, setIsAdded] = useState(false);

  const getColorHex = (name: string) => {
    const n = name.toLowerCase();
    if (n.includes('black') || n.includes('negra') || n.includes('obsidian') || n.includes('meteorite') || n.includes('carbon') || n.includes('midnight')) return '#1A1A1A';
    if (n.includes('white') || n.includes('blanca') || n.includes('arctic')) return '#FFFFFF';
    if (n.includes('gray') || n.includes('gris') || n.includes('steel') || n.includes('wolf')) return '#636366';
    if (n.includes('blue') || n.includes('azul') || n.includes('ocean') || n.includes('navy')) return '#004080';
    if (n.includes('rose gold')) return '#E6BE8A';
    if (n.includes('green') || n.includes('verde') || n.includes('forest') || n.includes('pine') || n.includes('sage')) return '#2D5A27';
    if (n.includes('purple') || n.includes('royal')) return '#800080';
    if (n.includes('pink') || n.includes('rosada') || n.includes('flamingo')) return '#FFC0CB';
    if (n.includes('red') || n.includes('lava')) return '#FF0000';
    if (n.includes('sand') || n.includes('desert') || n.includes('mocha')) return '#C2B280';
    if (n.includes('teal') || n.includes('lagoon')) return '#008080';
    if (n.includes('lavender')) return '#E6E6FA';
    if (n.includes('lilac')) return '#C8A2C8';
    if (n.includes('terracotta')) return '#B35C44';
    if (n.includes('silver')) return '#C0C0C0';
    return '#E5E5E5';
  };

  const handleAdd = () => {
    onAddToCart(product, selectedVariant.sku, quantity);
    setIsAdded(true);
    setTimeout(() => setIsAdded(false), 2000);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-4 md:py-8 animate-in fade-in duration-500">
      <nav className="mb-6">
        <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.2em] hover:text-black transition-colors">
          <span className="material-icons text-sm mr-1">arrow_back</span> Atrás al Catálogo
        </button>
      </nav>

      <div className="flex flex-col md:grid md:grid-cols-2 gap-8 lg:gap-16">
        {/* Imagen Dinámica - Única, cambia con el color */}
        <div className="relative group">
          <div className="bg-white rounded-2xl md:rounded-[40px] p-8 md:p-12 border border-black/[0.04] aspect-square flex items-center justify-center overflow-hidden shadow-sm transition-all duration-300 group-hover:shadow-md">
            <img 
              key={selectedVariant.sku}
              alt={product.title} 
              className="object-contain max-h-full w-auto mix-blend-multiply animate-in fade-in zoom-in-95 duration-500" 
              src={selectedVariant.image}
            />
          </div>
          {/* Badge de Stock en tiempo real */}
          <div className="absolute top-6 left-6 flex flex-col gap-2">
            <span className="text-[9px] font-black bg-black text-white px-3 py-1 rounded-full uppercase tracking-widest shadow-lg">
              Stock: {selectedVariant.inventory}
            </span>
            {selectedVariant.inventory < 100 && (
              <span className="text-[8px] font-black bg-red-500 text-white px-3 py-1 rounded-full uppercase tracking-widest shadow-lg">
                Bajo Inventario
              </span>
            )}
          </div>
        </div>

        {/* Panel de Control de Producto */}
        <div className="flex flex-col justify-center">
          <div className="mb-8 pb-8 border-b border-black/5">
            <div className="flex items-center gap-2 mb-2">
               <span className="text-[8px] md:text-[10px] font-black text-[#86868B] uppercase tracking-[0.3em]">{product.type}</span>
               <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
               <span className="text-[8px] md:text-[10px] font-black text-green-600 uppercase tracking-[0.3em]">Disponible B2B</span>
            </div>
            <h1 className="text-2xl md:text-4xl font-black text-black tracking-tight leading-none mb-4">{product.title}</h1>
            <div className="flex items-baseline gap-2">
              <span className="text-xl md:text-3xl font-black text-black tracking-tighter">${selectedVariant.price.toFixed(2)}</span>
              <span className="text-[10px] md:text-[12px] font-bold text-[#86868B] uppercase tracking-widest">/ Unidad Mayorista</span>
            </div>
            <p className="mt-4 text-[13px] md:text-[15px] text-[#424245] leading-relaxed font-medium opacity-80">
              {product.description}
            </p>
          </div>

          <div className="space-y-8">
            {/* Selector de Color Profesional - Burbujas sin miniaturas */}
            {product.variants.length > 1 && (
              <div>
                <div className="flex justify-between items-center mb-4">
                  <h3 className="text-[10px] font-black text-black uppercase tracking-widest">Colores Disponibles</h3>
                  <span className="text-[9px] font-bold text-[#86868B] uppercase bg-[#F5F5F7] px-2 py-0.5 rounded-md">{selectedVariant.option1}</span>
                </div>
                <div className="flex flex-wrap gap-3">
                  {product.variants.map((v) => (
                    <button 
                      key={v.sku}
                      onClick={() => setSelectedVariant(v)}
                      title={v.option1}
                      className={`w-10 h-10 md:w-12 md:h-12 rounded-full border-2 transition-all p-0.5 relative flex items-center justify-center ${selectedVariant.sku === v.sku ? 'border-black scale-110 shadow-lg' : 'border-transparent hover:scale-105'}`}
                    >
                      <div 
                        className="w-full h-full rounded-full border border-black/5" 
                        style={{ backgroundColor: getColorHex(v.option1) }}
                      />
                      {selectedVariant.sku === v.sku && (
                        <span className="absolute -bottom-1 -right-1 bg-black text-white w-4 h-4 rounded-full flex items-center justify-center border-2 border-white">
                          <span className="material-icons text-[10px]">check</span>
                        </span>
                      )}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Ajuste de Cantidad 1 a 1 */}
            <div>
              <h3 className="text-[10px] font-black text-black uppercase tracking-widest mb-4">Cantidad del Pedido</h3>
              <div className="flex items-center gap-6">
                <div className="flex items-center border border-black/5 rounded-2xl w-36 md:w-48 h-12 md:h-14 bg-[#F5F5F7] p-1 shadow-inner overflow-hidden">
                  <button onClick={() => setQuantity(q => Math.max(1, q - 1))} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black transition-colors">
                    <span className="material-icons text-lg">remove</span>
                  </button>
                  <input 
                    className="w-10 md:w-16 text-center bg-transparent border-none focus:ring-0 text-black font-black text-base md:text-xl" 
                    value={quantity} 
                    type="number"
                    min="1"
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                  />
                  <button onClick={() => setQuantity(q => q + 1)} className="flex-1 h-full flex items-center justify-center text-gray-400 hover:text-black transition-colors">
                    <span className="material-icons text-lg">add</span>
                  </button>
                </div>
                <div className="flex flex-col">
                  <span className="text-[8px] md:text-[10px] font-mono text-[#86868B] uppercase tracking-tighter">SKU REFERENCIA:</span>
                  <span className="text-[10px] md:text-[12px] font-black text-black">{selectedVariant.sku}</span>
                </div>
              </div>
            </div>

            {/* Acciones - No interrumpe navegación */}
            <div className="pt-4">
              <button 
                onClick={handleAdd}
                className={`w-full h-14 md:h-16 rounded-2xl shadow-xl transition-all active:scale-[0.97] uppercase text-[12px] md:text-[14px] tracking-[0.2em] flex items-center justify-center gap-3 font-black ${isAdded ? 'bg-green-600 text-white' : 'bg-black text-white hover:bg-[#1D1D1F]'}`}
              >
                <span className="material-icons text-lg md:text-xl">{isAdded ? 'done_all' : 'add_shopping_cart'}</span>
                {isAdded ? 'Añadido Correctamente' : 'Añadir al Pedido'}
              </button>
              <p className="mt-4 text-[9px] text-center text-[#86868B] font-bold uppercase tracking-widest leading-relaxed">
                Su selección se guardará en el carrito.<br/>Puede seguir explorando otros modelos.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetailView;

import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = (isEmail = false) => {
    // Encoding for breaks depending on platform
    const br = isEmail ? "%0D%0A" : "\n";
    let text = `*SOLICITUD DE PROFORMA - CUBITT PANAMÁ*${br}${br}`;
    text += `Lista de Artículos Solicitados:${br}`;
    text += `==============================${br}`;
    cart.forEach((item, index) => {
      text += `${index + 1}. ${item.product.title.toUpperCase()}${br}`;
      text += `   Variante: ${item.variant.option1}${br}`;
      text += `   SKU: ${item.variant.sku}${br}`;
      text += `   Cantidad: ${item.quantity}${br}`;
      text += `   Subtotal: $${(item.variant.price * item.quantity).toFixed(2)}${br}${br}`;
    });
    text += `==============================${br}`;
    text += `*SUBTOTAL:* $${subtotal.toFixed(2)}${br}`;
    text += `*ITBMS (7%):* $${tax.toFixed(2)}${br}`;
    text += `*TOTAL ESTIMADO:* $${total.toFixed(2)}${br}${br}`;
    text += `_Favor contactar para confirmar stock y tiempo de entrega._`;
    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText(false));
    window.open(`https://wa.me/50766778899?text=${message}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = "Solicitud de Proforma Corporativa Cubitt";
    const body = generateProformaText(true);
    // Use window.location.href for email to trigger default mail app better on mobile
    const mailtoUrl = `mailto:ventas@cubitt.com.pa?subject=${encodeURIComponent(subject)}&body=${body}`;
    window.location.href = mailtoUrl;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-24 text-center">
        <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6">
          <span className="material-icons text-[40px] text-[#D1D1D6]">shopping_bag</span>
        </div>
        <h2 className="text-xl font-black uppercase tracking-widest mb-4">Pedido Vacío</h2>
        <p className="text-[#86868B] mb-8 max-w-xs mx-auto text-sm font-medium">Añada productos del catálogo para generar su solicitud de proforma mayorista.</p>
        <button onClick={onBack} className="text-[11px] font-black uppercase tracking-widest bg-black text-white px-10 py-4 rounded-full shadow-xl hover:scale-105 transition-all">Explorar Catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 md:py-12 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex flex-col md:flex-row items-start md:items-center justify-between mb-8 gap-4">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.2em] mb-2 hover:text-black">
            <span className="material-icons text-xs mr-1">arrow_back</span> Volver
          </button>
          <h1 className="text-3xl md:text-4xl font-black text-black tracking-tighter uppercase">Revisar Solicitud</h1>
        </div>
        <div className="flex items-center gap-2 bg-green-50 px-4 py-2 rounded-full border border-green-100">
          <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></span>
          <span className="text-[10px] font-black text-green-700 uppercase tracking-widest">Canal Mayorista Directo</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-2xl md:rounded-[32px] border border-[#E5E5E5] overflow-hidden shadow-sm">
            <div className="p-6 border-b border-[#E5E5E5] flex justify-between items-center bg-[#F5F5F7]/30">
              <h2 className="text-[11px] md:text-sm font-black text-black uppercase tracking-widest">Resumen de Pedido ({cart.length})</h2>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[600px]">
