                onClick={() => setSelectedCategory(cat.name)}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all duration-300 w-full whitespace-nowrap ${
                  selectedCategory === cat.name 
                    ? 'bg-black text-white shadow-xl shadow-black/10 scale-[1.02]' 
                    : 'text-gray-600 hover:bg-[#F5F5F7] hover:text-black'
                }`}
              >
                <span className="material-icons text-base">{cat.icon}</span>
                <span className="text-[13px] font-black uppercase tracking-widest">{cat.name === 'All' ? 'Ver Todo' : cat.name}</span>
              </button>
            </li>
          ))}
        </ul>
      </div>

      <div className="hidden lg:block bg-gradient-to-br from-white to-[#F5F5F7] p-6 rounded-[24px] border border-black/5 shadow-sm">
        <div className="flex items-center gap-2 mb-3 text-black">
          <span className="material-icons text-lg">support_agent</span>
          <span className="text-[9px] font-black uppercase tracking-[0.2em]">Soporte B2B</span>
        </div>
        <p className="text-[11px] text-[#86868B] leading-relaxed font-bold uppercase tracking-tighter">
          Para órdenes especiales (+500 unidades) contactar a ventas@cubitt.com.pa
        </p>
      </div>
    </aside>
  );
};

export default Sidebar;

import React from 'react';
import { Product } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: string;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect }) => {
  // Sort products logically: Type then Title
  const sortedProducts = [...products].sort((a, b) => {
    if (a.type !== b.type) return a.type.localeCompare(b.type);
    return a.title.localeCompare(b.title);
  });

  return (
    <main className="flex-1 min-w-0 order-2 lg:order-1">
      <div className="mb-6 md:mb-10">
        <div className="flex items-center gap-2 text-[9px] md:text-[11px] font-black text-black uppercase tracking-[0.3em] mb-2">
          <span className="w-1.5 h-1.5 bg-black rounded-full"></span>
          Inventario Mayorista Oficial
        </div>
        <h1 className="text-2xl md:text-4xl font-black tracking-tighter text-black leading-none uppercase">
          {sortedProducts.length} Artículos en Stock
        </h1>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-5">
        {sortedProducts.map(product => (
          <div 
            key={product.id}
            onClick={() => onSelect(product)}
            className="group bg-white rounded-[24px] md:rounded-[32px] p-4 md:p-6 border border-black/[0.04] hover:border-black/10 hover:shadow-2xl hover:-translate-y-1 transition-all cursor-pointer flex flex-col relative overflow-hidden h-full"
          >
            {/* Type Badge */}
            <div className="flex justify-between items-start mb-4">
              <span className="text-[7px] md:text-[9px] font-black text-[#86868B] uppercase tracking-[0.2em] bg-[#F5F5F7] px-2 py-1 rounded-full">
                {product.type}
              </span>
              <span className="material-icons text-[12px] md:text-sm text-[#D1D1D6] group-hover:text-black transition-colors">add_circle_outline</span>
            </div>

            {/* Main Visual */}
            <div className="aspect-square mb-4 flex items-center justify-center p-2">
              <img 
                src={product.variants[0].image} 
                alt={product.title} 
                className="max-h-full w-auto object-contain mix-blend-multiply group-hover:scale-110 transition-transform duration-500"
              />
            </div>

            <div className="mt-auto">
              <h3 className="text-[11px] md:text-[14px] font-black text-[#1D1D1F] leading-tight group-hover:text-black transition-colors line-clamp-1 mb-1 uppercase tracking-tight">
                {product.title}
              </h3>
              <div className="flex items-center justify-between mt-2">
                <div className="text-[14px] md:text-[20px] font-black text-black leading-none tracking-tighter">
                  ${product.variants[0].price.toFixed(2)}
                </div>
                <div className="text-[8px] md:text-[10px] font-black text-[#86868B] uppercase tracking-widest bg-[#F5F5F7] px-2 py-0.5 rounded-md">
                   {product.variants.length} Colores
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {sortedProducts.length === 0 && (
        <div className="py-32 text-center">
          <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <span className="material-icons text-[32px] text-[#D1D1D6]">search_off</span>
          </div>
          <p className="text-[#86868B] text-xs font-black uppercase tracking-widest">Sin artículos disponibles en esta categoría</p>
        </div>
      )}
    </main>
  );
};

