import React, { useMemo } from 'react';
import { Product } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: string;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect, selectedCategory }) => {
  // Agrupar productos por TYPE
  const groupedProducts = useMemo(() => {
    const groups: Record<string, Product[]> = {};
    products.forEach(p => {
      if (!groups[p.type]) groups[p.type] = [];
      groups[p.type].push(p);
    });
    return groups;
  }, [products]);

  const typesOrder = ['Relojes', 'Termos', 'Audio', 'Accesorios'];

  return (
    <main className="flex-1 min-w-0 order-2 lg:order-1">
      <div className="mb-10">
        <div className="flex items-center gap-2 text-[10px] font-black text-black uppercase tracking-[0.4em] mb-2">
          <span className="w-2 h-2 bg-black rounded-full"></span>
          Stock Oficial Mayorista
        </div>
        <h1 className="text-3xl md:text-5xl font-black tracking-tighter text-black uppercase">
          Explorar Catálogo
        </h1>
      </div>

      <div className="space-y-16">
        {typesOrder.map(type => {
          const group = groupedProducts[type];
          if (!group || group.length === 0) return null;

          return (
            <section key={type} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="flex items-center gap-4 mb-6">
                <h2 className="text-xl font-black text-black uppercase tracking-widest">{type}</h2>
                <div className="h-px bg-black/5 flex-1" />
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{group.length} Modelos</span>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 md:gap-6">
                {group.map(product => (
                  <div 
                    key={product.id}
                    onClick={() => onSelect(product)}
                    className="group bg-white rounded-[32px] p-5 border border-black/[0.04] hover:border-black/10 hover:shadow-2xl transition-all cursor-pointer flex flex-col h-full"
                  >
                    <div className="aspect-square mb-4 flex items-center justify-center p-4 bg-[#F5F5F7] rounded-[24px] group-hover:bg-white transition-colors">
                      <img 
                        src={product.variants[0].image} 
                        alt={product.title} 
                        className="max-h-full w-auto object-contain mix-blend-multiply group-hover:scale-110 transition-transform duration-500"
                      />
                    </div>

                    <div className="mt-auto">
                      <div className="text-[9px] font-black text-[#86868B] uppercase tracking-widest mb-1">{product.vendor}</div>
                      <h3 className="text-[13px] md:text-[15px] font-black text-black leading-tight uppercase tracking-tight line-clamp-2">
                        {product.title}
                      </h3>
                      <div className="flex items-center justify-between mt-3">
                        <span className="text-lg font-black text-black tracking-tighter">
                          ${product.variants[0].price.toFixed(2)}
                        </span>
                        <div className="flex items-center gap-1 bg-black text-white text-[8px] font-black px-2 py-0.5 rounded-full uppercase tracking-tighter">
                          <span className="material-icons text-[10px]">palette</span>
                          {product.variants.length}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          );
        })}
      </div>

      {Object.keys(groupedProducts).length === 0 && (
        <div className="py-40 text-center">
          <span className="material-icons text-[48px] text-[#D1D1D6] mb-4">inventory_2</span>
          <p className="text-[#86868B] text-xs font-black uppercase tracking-[0.2em]">No se encontraron artículos</p>
        </div>
      )}
    </main>
  );
};

