import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = (platform: 'whatsapp' | 'email') => {
    // Definir saltos de línea según plataforma (\r\n para mailto es más compatible)
    const br = platform === 'email' ? "%0D%0A" : "\n";
    const divider = "------------------------------";

    let text = `SOLICITUD DE PROFORMA - CUBITT PANAMA${br}${br}`;
    text += `Detalle del Pedido B2B:${br}`;
    text += `${divider}${br}`;

    cart.forEach((item, index) => {
      text += `${index + 1}. ${item.product.title.toUpperCase()}${br}`;
      text += `   - Color: ${item.variant.option1}${br}`;
      text += `   - SKU: ${item.variant.sku}${br}`;
      text += `   - Cant: ${item.quantity} unds.${br}`;
      text += `   - Subtotal: $${(item.variant.price * item.quantity).toFixed(2)}${br}${br}`;
    });

    text += `${divider}${br}`;
    text += `SUBTOTAL: $${subtotal.toFixed(2)}${br}`;
    text += `ITBMS (7%): $${tax.toFixed(2)}${br}`;
    text += `TOTAL ESTIMADO: $${total.toFixed(2)}${br}${br}`;
    text += `Nota: Precios sujetos a confirmación de stock.`;

    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText('whatsapp'));
    window.open(`https://wa.me/50766778899?text=${message}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("Solicitud de Cotización Mayorista - Cubitt Panamá");
    // Usamos el texto pre-formateado con %0D%0A para los saltos de línea de email
    const body = generateProformaText('email');

    const mailtoUrl = `mailto:ventas@cubitt.com.pa?subject=${subject}&body=${body}`;

    // Intentamos abrir el cliente de correo
    window.location.href = mailtoUrl;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-24 text-center">
        <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6">
          <span className="material-icons text-[40px] text-[#D1D1D6]">shopping_bag</span>
        </div>
        <h2 className="text-xl font-black uppercase tracking-widest mb-4">Carrito Vacío</h2>
        <button onClick={onBack} className="text-[11px] font-black uppercase tracking-widest bg-black text-white px-10 py-4 rounded-full shadow-xl hover:scale-105 transition-all">Ir al Catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 md:py-16 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex flex-col md:flex-row items-start justify-between mb-12 gap-6">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.3em] mb-4 hover:text-black">
            <span className="material-icons text-sm mr-1">arrow_back</span> Atrás
          </button>
          <h1 className="text-4xl md:text-6xl font-black text-black tracking-tighter uppercase leading-none">Revisar Pedido</h1>
        </div>
        <div className="bg-green-600 text-white px-6 py-3 rounded-full flex items-center gap-2 shadow-lg">
          <span className="material-icons text-sm">verified</span>
          <span className="text-[10px] font-black uppercase tracking-widest">Validación Mayorista</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[40px] border border-black/5 overflow-hidden shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[650px]">
                <thead>
                  <tr className="bg-[#F5F5F7] text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-black/5">
                    <th className="px-8 py-6">Producto y SKU</th>
                    <th className="px-8 py-6 text-center">Cantidad</th>
                    <th className="px-8 py-6 text-right">Monto</th>
                    <th className="px-8 py-6 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-black/5">
                  {cart.map((item) => (
                    <tr key={item.variant.sku} className="hover:bg-[#F5F5F7]/30 transition-colors group">
                      <td className="px-8 py-8">
                        <div className="flex items-center gap-6">
                          <div className="h-16 w-16 bg-[#F5F5F7] rounded-2xl p-2 shrink-0 flex items-center justify-center border border-black/5">
                            <img src={item.variant.image} className="h-full w-auto object-contain mix-blend-multiply" />
                          </div>
                          <div>
                            <div className="text-[15px] font-black text-black leading-none mb-2 uppercase tracking-tight">{item.product.title}</div>
                            <div className="flex items-center gap-2">
                              <span className="text-[10px] font-bold text-[#86868B] uppercase">{item.variant.option1}</span>
                              <span className="text-gray-200">|</span>
                              <span className="text-[10px] font-mono text-black font-black uppercase">{item.variant.sku}</span>
                            </div>
                          </div>
                        </div>
                      </td>
                      <td className="px-8 py-8">
                        <div className="flex items-center justify-center border border-black/10 rounded-full h-10 w-32 mx-auto bg-white shadow-inner">
                          <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity - 1)} className="flex-1 text-gray-400 font-bold hover:text-black">-</button>
                          <span className="flex-1 text-center text-sm font-black text-black">{item.quantity}</span>
                          <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity + 1)} className="flex-1 text-gray-400 font-bold hover:text-black">+</button>
                        </div>
                      </td>
                      <td className="px-8 py-8 text-right text-lg font-black text-black tracking-tighter">
                        ${(item.variant.price * item.quantity).toFixed(2)}
                      </td>
                      <td className="px-8 py-8 text-right">
                        <button onClick={() => onRemove(item.variant.sku)} className="text-gray-300 hover:text-red-500 transition-all opacity-0 group-hover:opacity-100">
                          <span className="material-icons">delete_sweep</span>
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div className="lg:col-span-4">
          <div className="bg-white rounded-[40px] border border-black/5 p-10 sticky top-24 shadow-2xl shadow-black/5">
            <h2 className="text-[11px] font-black text-black uppercase tracking-[0.3em] mb-10">Resumen Financiero</h2>
            <div className="space-y-6 mb-10">
              <div className="flex justify-between text-sm text-[#86868B] font-bold uppercase tracking-widest">
                <span>Subtotal Neto</span>
                <span className="text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm text-[#86868B] font-bold uppercase tracking-widest">
                <span>ITBMS (7%)</span>
                <span className="text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="h-px bg-black/5 my-6" />
              <div className="flex justify-between items-end">
                <span className="text-[10px] font-black text-black uppercase tracking-[0.4em]">Total Proforma</span>
                <div className="text-right leading-none">
                  <span className="text-4xl md:text-5xl font-black text-black tracking-tighter">${total.toFixed(2)}</span>
                  <span className="block text-[8px] font-black text-[#86868B] uppercase mt-2 tracking-widest">Dólares (USD)</span>
                </div>
              </div>
            </div>

            <div className="grid gap-3">
              <button 
                onClick={handleWhatsApp}
                className="h-16 bg-[#25D366] text-white rounded-[20px] font-black text-[13px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:brightness-105 transition-all shadow-xl shadow-green-100"
              >
                <span className="material-icons">whatsapp</span>
                Confirmar WhatsApp
              </button>
              <button 
                onClick={handleEmail}
                className="h-16 bg-black text-white rounded-[20px] font-black text-[13px] uppercase tracking-[0.2em] flex items-center justify-center gap-3 hover:bg-[#1D1D1F] transition-all shadow-xl"
              >
                <span className="material-icons">alternate_email</span>
                Solicitar por Email
              </button>
              <p className="text-[9px] text-center text-[#86868B] font-bold uppercase tracking-widest mt-4">
                Canal exclusivo para distribuidores autorizados.
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ReviewOrderView;

import React, { useMemo } from 'react';
import { Product } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: string;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect, selectedCategory }) => {
  // Agrupar productos por TYPE
  const groupedProducts = useMemo(() => {
    const groups: Record<string, Product[]> = {};
    products.forEach(p => {
      const type = p.type || 'Otros';
      if (!groups[type]) groups[type] = [];
      groups[type].push(p);
    });
    return groups;
  }, [products]);

  // Orden de secciones
  const typesOrder = ['Relojes', 'Termos', 'Audio', 'Accesorios'];

  return (
    <main className="flex-1 min-w-0 order-2 lg:order-1">
      <div className="mb-12">
        <div className="flex items-center gap-2 text-[10px] font-black text-black uppercase tracking-[0.4em] mb-2">
          <span className="w-2 h-2 bg-black rounded-full"></span>
          Stock Oficial Corporativo
        </div>
        <h1 className="text-3xl md:text-5xl font-black tracking-tighter text-black uppercase">
          {products.length} Artículos Disponibles
        </h1>
      </div>

      <div className="space-y-20">
        {typesOrder.map(type => {
          const group = groupedProducts[type];
          if (!group || group.length === 0) return null;

          return (
            <section key={type} className="animate-in fade-in slide-in-from-bottom-4 duration-700">
              <div className="flex items-center gap-6 mb-8">
                <h2 className="text-2xl font-black text-black uppercase tracking-widest">{type}</h2>
                <div className="h-px bg-black/10 flex-1" />
                <span className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">{group.length} Referencias</span>
              </div>

              <div className="grid grid-cols-2 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 md:gap-8">
                {group.map(product => (
                  <div 
                    key={product.id}
                    onClick={() => onSelect(product)}
                    className="group bg-white rounded-[40px] p-6 border border-black/[0.04] hover:border-black/10 hover:shadow-2xl transition-all cursor-pointer flex flex-col h-full"
                  >
                    <div className="aspect-square mb-6 flex items-center justify-center p-6 bg-[#F5F5F7] rounded-[32px] group-hover:bg-white transition-colors duration-500">
                      <img 
                        src={product.variants[0].image} 
                        alt={product.title} 
                        className="max-h-full w-auto object-contain mix-blend-multiply group-hover:scale-110 transition-transform duration-700"
                      />
                    </div>

                    <div className="mt-auto">
                      <div className="text-[9px] font-black text-[#86868B] uppercase tracking-[0.2em] mb-2">{product.vendor}</div>
                      <h3 className="text-[14px] md:text-[16px] font-black text-black leading-tight uppercase tracking-tight line-clamp-2 mb-3">
                        {product.title}
                      </h3>
                      <div className="flex items-center justify-between">
                        <span className="text-xl font-black text-black tracking-tighter">
                          ${product.variants[0].price.toFixed(2)}
                        </span>
                        <div className="bg-black text-white text-[9px] font-black px-3 py-1 rounded-full uppercase tracking-tighter">
                          {product.variants.length} SKU
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          );
        })}
      </div>

      {Object.keys(groupedProducts).length === 0 && (
        <div className="py-40 text-center">
          <span className="material-icons text-[48px] text-[#D1D1D6] mb-4">inventory_2</span>
          <p className="text-[#86868B] text-xs font-black uppercase tracking-[0.2em]">No hay coincidencias en el catálogo</p>
        </div>
      )}
    </main>
  );
};

