import React, { useMemo } from 'react';
import { Product } from '../types';

interface ProductGridProps {
  products: Product[];
  onSelect: (p: Product) => void;
  selectedCategory: string;
}

const ProductGrid: React.FC<ProductGridProps> = ({ products, onSelect, selectedCategory }) => {
  const groupedProducts = useMemo(() => {
    const groups: Record<string, Product[]> = {};
    products.forEach(p => {
      const cat = p.category || 'Otros';
      if (!groups[cat]) groups[cat] = [];
      groups[cat].push(p);
    });
    return groups;
  }, [products]);

  const typesOrder = ['Relojes', 'Termos', 'Audio', 'Accesorios'];

  return (
    <main className="flex-1 min-w-0 order-2 lg:order-1">
      <div className="mb-10">
        <h1 className="text-4xl font-black tracking-tight text-black uppercase mb-2">
          Inventario Corporativo
        </h1>
        <p className="text-[#86868B] text-xs font-bold uppercase tracking-[0.2em]">
          Seleccione un modelo para ver SKUs y existencias detalladas
        </p>
      </div>

      <div className="space-y-12">
        {typesOrder.map(type => {
          const group = groupedProducts[type];
          if (!group || group.length === 0) return null;

          return (
            <section key={type} className="animate-in fade-in slide-in-from-bottom-2 duration-500">
              <div className="flex items-center gap-4 mb-4 border-b-2 border-black pb-2">
                <h2 className="text-lg font-black text-black uppercase tracking-widest">{type}</h2>
                <span className="text-[10px] font-black bg-black text-white px-2 py-0.5 rounded-md uppercase">
                  {group.length} REFERENCIAS
                </span>
              </div>

