                  <table className="w-full text-left border-collapse">
                    <thead className="bg-[#F5F5F7]">
                      <tr className="text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-black/5">
                        <th className="px-6 py-4">Modelo</th>
                        <th className="px-6 py-4">Descripción Técnica</th>
                        <th className="px-6 py-4">Precio Base</th>
                        <th className="px-6 py-4">Opciones</th>
                        <th className="px-6 py-4 text-right">Acción</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-black/5">
                      {group.map(product => (
                        <tr 
                          key={product.id}
                          className="hover:bg-black/5 transition-colors cursor-pointer group"
                          onClick={() => onSelect(product)}
                        >
                          <td className="px-6 py-5">
                            <div className="text-[13px] font-black text-black uppercase tracking-tight">
                              {product.title}
                            </div>
                            <div className="text-[10px] text-[#86868B] font-mono mt-1">
                              ID: {product.handle.toUpperCase()}
                            </div>
                          </td>
                          <td className="px-6 py-5">
                            <p className="text-[12px] text-[#424245] leading-tight font-medium max-w-xs">
                              {product.description}
                            </p>
                          </td>
                          <td className="px-6 py-5">
                            <span className="text-[14px] font-black text-black">
                              ${product.variants[0].price.toFixed(2)}
                            </span>
                          </td>
                          <td className="px-6 py-5">
                            <span className="text-[10px] font-bold text-[#86868B] uppercase">
                              {product.variants.length} Variantes
                            </span>
                          </td>
                          <td className="px-6 py-5 text-right">
                            <button className="bg-black text-white text-[10px] font-black px-4 py-2 rounded-lg uppercase tracking-widest group-hover:bg-black/80 transition-all">
                              Ver Ficha
                            </button>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </section>
          );
        })}
      </div>

      {products.length === 0 && (
        <div className="py-20 text-center border-2 border-dashed border-gray-200 rounded-3xl">
          <span className="material-icons text-[40px] text-gray-300 mb-2">search_off</span>
          <p className="text-gray-400 text-xs font-black uppercase tracking-widest">
            Sin resultados para la búsqueda actual
          </p>
        </div>
      )}
    </main>
  );
};

