                      <span className="material-icons">add</span>
                    </button>
                  </div>
                </div>
                <div className="flex-1 w-full">
                  <div className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-2">Total Item</div>
                  <div className="text-3xl font-black text-black tracking-tighter h-14 flex items-center">
                    ${(selectedVariant.price * quantity).toFixed(2)}
                  </div>
                </div>
              </div>

              <button 
                onClick={handleAdd}
                className={`w-full mt-8 h-16 rounded-2xl font-black text-sm uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 shadow-xl ${
                  isAdded ? 'bg-accent-green text-white' : 'bg-black text-white hover:bg-black/90 active:scale-[0.98]'
                }`}
              >
                <span className="material-icons">{isAdded ? 'check_circle' : 'add_shopping_cart'}</span>
                {isAdded ? 'Añadido a la Orden' : 'Cargar a la Proforma'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

