import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = () => {
    const br = "\n";
    const divider = "━━━━━━━━━━━━━━━━━━━━";

    let text = `📦 *CUBITT PANAMA - ORDEN B2B*${br}${br}`;
    text += `*RESUMEN DE PROFORMA*${br}`;
    text += `${divider}${br}`;

    cart.forEach((item, index) => {
      text += `${index + 1}. *${item.product.title.toUpperCase()}*${br}`;
      text += `   SKU: \`${item.variant.sku}\`${br}`;
      text += `   Color: ${item.variant.option1}${br}`;
      text += `   Cantidad: ${item.quantity} unds.${br}`;
      text += `   Subtotal: $${(item.variant.price * item.quantity).toFixed(2)}${br}${br}`;
    });

    text += `${divider}${br}`;
    text += `*SUBTOTAL:* $${subtotal.toFixed(2)}${br}`;
    text += `*ITBMS (7%):* $${tax.toFixed(2)}${br}`;
    text += `*TOTAL A PAGAR: $${total.toFixed(2)}*${br}${br}`;
    text += `_Generado desde Portal Mayorista Cubitt_`;

    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText());
    // Número actualizado a +50761541129
    window.open(`https://wa.me/50761541129?text=${message}`, '_blank');
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-24 text-center">
        <div className="w-20 h-20 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-6">
          <span className="material-icons text-[40px] text-[#D1D1D6]">shopping_bag</span>
        </div>
        <h2 className="text-xl font-black uppercase tracking-widest mb-4">La Proforma está vacía</h2>
        <button onClick={onBack} className="text-[11px] font-black uppercase tracking-widest bg-black text-white px-10 py-4 rounded-full shadow-xl hover:scale-105 transition-all">Ir al Catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 md:py-16 animate-in fade-in slide-in-from-bottom-2 duration-300">
      <div className="flex flex-col md:flex-row items-start justify-between mb-12 gap-6">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.3em] mb-4 hover:text-black">
            <span className="material-icons text-sm mr-1">arrow_back</span> Regresar
          </button>
          <h1 className="text-4xl md:text-6xl font-black text-black tracking-tighter uppercase leading-none">Revisar Orden</h1>
        </div>
        <div className="bg-[#10B981] text-white px-6 py-3 rounded-full flex items-center gap-2 shadow-lg">
          <span className="material-icons text-sm">verified</span>
          <span className="text-[10px] font-black uppercase tracking-widest">Validación Mayorista</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[40px] border border-black/5 overflow-hidden shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse min-w-[650px]">
                <thead>
                  <tr className="bg-[#F5F5F7] text-[10px] font-black text-gray-400 uppercase tracking-widest border-b border-black/5">
                    <th className="px-8 py-6">Especificación Técnica</th>
                    <th className="px-8 py-6 text-center">Cantidad</th>
                    <th className="px-8 py-6 text-right">Monto</th>
                    <th className="px-8 py-6 w-10"></th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-black/5">
                  {cart.map((item) => (
                    <tr key={item.variant.sku} className="hover:bg-[#F5F5F7]/30 transition-colors group">
                      <td className="px-8 py-8">
                        <div className="flex items-center gap-6">
                          <div className="h-16 w-16 bg-[#F5F5F7] rounded-2xl p-2 shrink-0 flex items-center justify-center border border-black/5">
                            <img src={item.variant.image} className="h-full w-auto object-contain mix-blend-multiply" />
                          </div>
                          <div>
                            <div className="text-[15px] font-black text-black leading-none mb-2 uppercase tracking-tight">{item.product.title}</div>
