import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const generateProformaText = () => {
    const br = "\n";
    const divider = "──────────────────";

    let text = `🚀 *ORDEN MAYORISTA CUBITT PANAMA*${br}${br}`;
    text += `*DETALLE DE PROFORMA*${br}`;
    text += `${divider}${br}`;

    cart.forEach((item, index) => {
      text += `${index + 1}. *${item.product.title.toUpperCase()}*${br}`;
      text += `   • SKU: \`${item.variant.sku}\`${br}`;
      text += `   • Color: ${item.variant.option1}${br}`;
      text += `   • Qty: ${item.quantity} unds.${br}`;
      text += `   • Sub: $${(item.variant.price * item.quantity).toFixed(2)}${br}${br}`;
    });

    text += `${divider}${br}`;
    text += `*SUBTOTAL:* $${subtotal.toFixed(2)}${br}`;
    text += `*ITBMS (7%):* $${tax.toFixed(2)}${br}`;
    text += `*TOTAL FINAL: $${total.toFixed(2)}*${br}${br}`;
    text += `_Enviado desde el Portal B2B Oficial_`;

    return text;
  };

  const handleWhatsApp = () => {
    const message = encodeURIComponent(generateProformaText());
    // Número actualizado: +50761541129
    window.open(`https://wa.me/50761541129?text=${message}`, '_blank');
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-32 text-center">
        <div className="w-24 h-24 bg-white border border-black/5 rounded-full flex items-center justify-center mx-auto mb-8 shadow-xl">
          <span className="material-icons text-5xl text-[#D1D1D6]">receipt_long</span>
        </div>
        <h2 className="text-2xl font-black uppercase tracking-widest mb-6">No hay items en la proforma</h2>
        <button onClick={onBack} className="text-[12px] font-black uppercase tracking-[0.3em] bg-black text-white px-12 py-5 rounded-full shadow-2xl hover:scale-105 active:scale-95 transition-all">Explorar Inventario</button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 md:py-16 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col md:flex-row items-start justify-between mb-12 gap-8">
        <div>
          <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.4em] mb-6 hover:text-black transition-colors">
