import React, { useState } from 'react';
import { Product, ProductVariant } from '../types';
import { COLOR_MAP } from '../constants';

interface ProductDetailViewProps {
  product: Product;
  onAddToCart: (p: Product, variantSku: string, quantity: number) => void;
  onBack: () => void;
}

const ProductDetailView: React.FC<ProductDetailViewProps> = ({ product, onAddToCart, onBack }) => {
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(product.variants[0]);
  const [quantity, setQuantity] = useState(1);
  const [isAdded, setIsAdded] = useState(false);

  const itemTotal = (selectedVariant.price * quantity).toFixed(2);

  const handleAdd = () => {
    onAddToCart(product, selectedVariant.sku, quantity);
    setIsAdded(true);
    setTimeout(() => setIsAdded(false), 2000);
  };

  return (
    <div className="max-w-7xl mx-auto px-4 py-8 animate-in fade-in duration-500">
      <nav className="mb-8">
        <button onClick={onBack} className="flex items-center text-[10px] font-black text-[#86868B] uppercase tracking-[0.4em] hover:text-black transition-colors">
          <span className="material-icons text-sm mr-2">west</span> Volver al Inventario
        </button>
      </nav>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 bg-white rounded-[48px] border border-black/5 p-6 md:p-12 shadow-2xl shadow-black/5">

        {/* Imagen Dinámica del SKU */}
        <div className="lg:col-span-6 flex items-center justify-center bg-[#F5F5F7] rounded-[40px] p-10 min-h-[400px] md:min-h-[550px] relative overflow-hidden group">
          <div className="absolute top-6 left-6 flex flex-col gap-2">
            <span className="bg-white/80 backdrop-blur px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-black/5">
              Ref: {selectedVariant.sku}
            </span>
          </div>
          {selectedVariant.image ? (
            <img 
              src={selectedVariant.image} 
              alt={selectedVariant.sku} 
              className="max-w-full max-h-[480px] object-contain mix-blend-multiply transition-all duration-700 group-hover:scale-110"
            />
          ) : (
            <span className="material-icons text-6xl text-gray-200">image</span>
          )}
        </div>

        {/* Configuración de Compra B2B */}
        <div className="lg:col-span-6 flex flex-col justify-between py-4">
          <div>
            <header className="mb-10 pb-8 border-b border-black/5">
              <div className="text-[10px] font-black text-link-blue uppercase tracking-[0.3em] mb-4">
                {product.category} • {product.type}
              </div>
              <h1 className="text-4xl md:text-6xl font-black text-black tracking-tighter uppercase leading-[0.9] mb-6">
                {product.title}
              </h1>
              <p className="text-lg text-[#424245] font-medium leading-snug uppercase tracking-tight opacity-60">
                {product.description}
              </p>
            </header>

            {/* Selector de Variantes con Círculos */}
            <div className="mb-12">
              <h3 className="text-[10px] font-black text-[#86868B] uppercase tracking-[0.3em] mb-6">Variantes de Color</h3>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                {product.variants.map((v) => (
                  <button 
                    key={v.sku}
                    onClick={() => setSelectedVariant(v)}
                    className={`flex items-center gap-3 p-4 rounded-2xl border-2 transition-all ${
                      selectedVariant.sku === v.sku 
                        ? 'border-black bg-black text-white shadow-xl' 
                        : 'border-black/5 hover:border-black/20 bg-white'
                    }`}
                  >
                    <div 
                      className={`w-5 h-5 rounded-full border border-black/10 shrink-0 ${selectedVariant.sku === v.sku ? 'ring-2 ring-white ring-offset-2 ring-offset-black' : ''}`}
                      style={{ backgroundColor: COLOR_MAP[v.option1] || '#CCCCCC' }}
                    />
                    <div className="text-left">
                      <div className="text-[10px] font-black uppercase truncate leading-none mb-1">{v.option1}</div>
                      <div className="text-[9px] font-mono opacity-50">${v.price.toFixed(2)}</div>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Tarjeta de Acción Pro - Subtotal Integrado */}
          <div className="bg-[#1D1D1F] rounded-[32px] p-8 md:p-10 text-white shadow-2xl">
            <div className="grid grid-cols-2 gap-8 mb-10 border-b border-white/10 pb-8">
              <div className="flex flex-col">
                <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-4">Cantidad Unidades</label>
                <div className="flex items-center bg-white/5 border border-white/10 rounded-2xl h-14 px-2">
                  <button 
                    onClick={() => setQuantity(q => Math.max(1, q - 1))} 
                    className="w-10 h-10 flex items-center justify-center hover:bg-white/10 rounded-xl"
                  >
                    <span className="material-icons text-sm">remove</span>
                  </button>
                  <input 
                    type="number" 
                    className="flex-1 bg-transparent border-none text-center font-black text-xl focus:ring-0" 
                    value={quantity}
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                  />
                  <button 
                    onClick={() => setQuantity(q => q + 1)} 
                    className="w-10 h-10 flex items-center justify-center hover:bg-white/10 rounded-xl"
                  >
                    <span className="material-icons text-sm">add</span>
                  </button>
                </div>
              </div>

              <div className="flex flex-col text-right">
                <span className="text-[9px] font-black text-gray-500 uppercase tracking-widest mb-4">Monto Parcial</span>
                <div className="text-4xl md:text-5xl font-black tracking-tighter leading-none h-14 flex items-center justify-end">
                  ${itemTotal}
                </div>
              </div>
            </div>

            <button 
              onClick={handleAdd}
              className={`w-full h-20 rounded-[22px] font-black text-[13px] uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-4 ${
                isAdded ? 'bg-[#10B981] text-white' : 'bg-white text-black hover:bg-gray-100 active:scale-95 shadow-xl'
              }`}
            >
              <span className="material-icons">{isAdded ? 'done_all' : 'add_shopping_cart'}</span>
              {isAdded ? 'SKU Añadido Correctamente' : 'Cargar a la Proforma'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

