                <div className="text-[8px] font-black text-gray-500 uppercase tracking-widest mb-2 text-center">Cantidad</div>
                <div className="flex items-center bg-white/10 rounded-xl border border-white/5 h-10 px-1">
                  <button 
                    onClick={() => setQuantity(q => Math.max(1, q - 1))} 
                    className="w-8 h-8 flex items-center justify-center hover:bg-white/20 rounded-lg text-white z-10"
                  >
                    <span className="material-icons text-xs">remove</span>
                  </button>
                  <input 
                    type="number" 
                    className="flex-1 bg-transparent border-none text-center font-black text-sm focus:ring-0 text-white p-0 pointer-events-none" 
                    value={quantity}
                    readOnly
                  />
                  <button 
                    onClick={() => setQuantity(q => q + 1)} 
                    className="w-8 h-8 flex items-center justify-center hover:bg-white/20 rounded-lg text-white z-10"
                  >
                    <span className="material-icons text-xs">add</span>
                  </button>
                </div>
              </div>

              <div className="text-right flex-1 border-l border-white/10 pl-4">
                <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest block mb-1">Monto Parcial</span>
                <div className="text-2xl font-black tracking-tighter">
                  ${itemTotal}
                </div>
              </div>
            </div>

            <button 
              onClick={handleAdd}
              className={`w-full h-12 rounded-[14px] font-black text-[10px] uppercase tracking-widest transition-all flex items-center justify-center gap-2 ${
                isAdded ? 'bg-accent-green text-white' : 'bg-white text-black hover:bg-gray-100'
              }`}
            >
              <span className="material-icons text-sm">{isAdded ? 'done' : 'shopping_cart'}</span>
              {isAdded ? 'Añadido' : 'Cargar a Proforma'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

