import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const buildOrderText = () => {
    const br = "\n";
    let text = `📦 *ORDEN B2B CUBITT*${br}${br}`;
    cart.forEach((item, i) => {
      text += `${i+1}. ${item.product.title} (${item.variant.option1})${br}SKU: ${item.variant.sku} | Qty: ${item.quantity}${br}${br}`;
    });
    text += `*TOTAL: $${total.toFixed(2)}*`;
    return text;
  };

  const handleWhatsApp = () => {
    const url = `https://wa.me/50761541129?text=${encodeURIComponent(buildOrderText())}`;
    window.open(url, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("Solicitud de Orden B2B - Cubitt Panama");
    const body = encodeURIComponent(buildOrderText());
    window.location.href = `mailto:ventas@cubitt.com?subject=${subject}&body=${body}`;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-24 text-center">
        <h2 className="text-xl font-black uppercase tracking-widest mb-6">Proforma Vacía</h2>
        <button onClick={onBack} className="bg-black text-white px-8 py-3 rounded-full text-[10px] font-black uppercase tracking-widest">Regresar al catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-6 animate-in fade-in duration-300">
      <div className="flex flex-col md:flex-row justify-between items-end mb-10 gap-4">
        <div>
          <button onClick={onBack} className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-1">
            <span className="material-icons text-xs">west</span> Catálogo
          </button>
          <h1 className="text-3xl font-black text-black uppercase tracking-tighter">Resumen de Orden</h1>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[24px] border border-black/5 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-[#F5F5F7] text-[8px] font-black text-gray-400 uppercase tracking-widest">
                <tr>
                  <th className="px-6 py-4">Item / SKU</th>
                  <th className="px-6 py-4 text-center">Qty</th>
                  <th className="px-6 py-4 text-right">Subtotal</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/5">
                {cart.map(item => (
                  <tr key={item.variant.sku} className="group hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-6">
                      <div className="flex items-center gap-4">
                        <img src={item.variant.image} className="w-12 h-12 object-contain bg-[#F5F5F7] rounded-lg p-1" />
                        <div>
                          <div className="text-[11px] font-black uppercase text-black leading-none mb-1">{item.product.title}</div>
                          <div className="text-[8px] font-mono text-gray-400">{item.variant.sku} • {item.variant.option1}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-6">
                      <div className="flex items-center justify-center bg-white border border-black/10 rounded-lg h-8 w-20 mx-auto overflow-hidden">
                        <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity - 1)} className="flex-1 hover:bg-gray-100 text-[10px]">-</button>
                        <span className="text-[10px] font-bold w-6 text-center">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity + 1)} className="flex-1 hover:bg-gray-100 text-[10px]">+</button>
                      </div>
                    </td>
                    <td className="px-6 py-6 text-right">
                      <div className="text-xs font-black">${(item.variant.price * item.quantity).toFixed(2)}</div>
                      <button onClick={() => onRemove(item.variant.sku)} className="text-[7px] text-red-500 font-black uppercase mt-1 opacity-0 group-hover:opacity-100">Remover</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="lg:col-span-4">
          <div className="bg-white rounded-[24px] border border-black/5 p-8 sticky top-24 shadow-xl">
            <h2 className="text-[9px] font-black text-black uppercase tracking-widest mb-8 text-center">Resumen de Pago</h2>
            <div className="space-y-4 mb-8">
              <div className="flex justify-between text-[10px] text-gray-400 font-bold uppercase">
                <span>Neto</span>
                <span className="text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-[10px] text-gray-400 font-bold uppercase">
                <span>ITBMS (7%)</span>
                <span className="text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="pt-4 border-t border-black/5 flex justify-between items-baseline">
                <span className="text-[10px] font-black">TOTAL</span>
                <span className="text-4xl font-black text-black tracking-tighter">${total.toFixed(2)}</span>
              </div>
            </div>

            <div className="space-y-3">
              <button 
                onClick={handleWhatsApp}
                className="w-full h-14 bg-black text-white rounded-[16px] text-[10px] font-black uppercase tracking-widest hover:bg-[#1D1D1F] active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <span className="material-icons text-sm">chat</span> Enviar por WhatsApp
              </button>
              <button 
                onClick={handleEmail}
                className="w-full h-12 bg-[#F5F5F7] text-black rounded-[16px] text-[10px] font-black uppercase tracking-widest hover:bg-[#EBEBEB] active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <span className="material-icons text-sm">mail_outline</span> Enviar por Correo
              </button>
            </div>
          </div>
