                    <span className="material-icons text-xs">add</span>
                  </button>
                </div>
              </div>

              <div className="text-right flex-1 border-l border-white/10 pl-4">
                <span className="text-[8px] font-black text-gray-500 uppercase tracking-widest block mb-1">Monto Subtotal</span>
                <div className="text-xl font-black tracking-tighter">
                  ${itemTotal}
                </div>
              </div>
            </div>

            <button 
              onClick={handleAdd}
              className={`w-full h-11 rounded-[12px] font-black text-[9px] uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-2 ${
                isAdded ? 'bg-accent-green text-white' : 'bg-white text-black hover:bg-gray-100'
              }`}
            >
              <span className="material-icons text-xs">{isAdded ? 'done' : 'shopping_cart'}</span>
              {isAdded ? 'Añadido' : 'Cargar a Proforma'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

