import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const buildOrderText = () => {
    const br = "\n";
    let text = `📦 *ORDEN B2B CUBITT*${br}${br}`;
    cart.forEach((item, i) => {
      text += `${i+1}. ${item.product.title}${br}SKU: ${item.variant.sku} | Cant: ${item.quantity}${br}${br}`;
    });
    text += `*TOTAL FINAL: $${total.toFixed(2)}*`;
    return text;
  };

  const handleWhatsApp = () => {
    window.open(`https://wa.me/50761541129?text=${encodeURIComponent(buildOrderText())}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("Solicitud de Orden B2B - Cubitt");
    const body = encodeURIComponent(buildOrderText());
    window.location.href = `mailto:ventas@cubitt.com?subject=${subject}&body=${body}`;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-xl mx-auto px-4 py-20 text-center">
        <div className="w-16 h-16 bg-white border border-black/5 rounded-full flex items-center justify-center mx-auto mb-6 shadow-sm">
          <span className="material-icons text-gray-200">shopping_bag</span>
        </div>
        <h2 className="text-sm font-black uppercase tracking-[0.3em] mb-4">La proforma está vacía</h2>
        <button onClick={onBack} className="bg-black text-white px-8 py-3 rounded-full text-[9px] font-black uppercase tracking-widest">Volver al catálogo</button>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto px-4 py-6 animate-in fade-in duration-300">
      <div className="mb-6">
        <button onClick={onBack} className="text-[8px] font-black text-gray-400 uppercase tracking-widest mb-2 flex items-center gap-1">
          <span className="material-icons text-[10px]">west</span> Regresar
        </button>
        <h1 className="text-2xl font-black text-black uppercase tracking-tight">Confirmar Requerimiento</h1>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[20px] border border-black/5 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-[#F5F5F7] text-[7px] font-black text-gray-400 uppercase tracking-[0.3em]">
                <tr>
                  <th className="px-6 py-3">Línea de SKU</th>
                  <th className="px-6 py-3 text-center">Qty</th>
                  <th className="px-6 py-3 text-right">Subtotal</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/5 text-[10px]">
                {cart.map(item => (
                  <tr key={item.variant.sku} className="group hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-[#F5F5F7] rounded-lg p-1 shrink-0 flex items-center justify-center border border-black/5">
                          {item.variant.image ? <img src={item.variant.image} className="max-h-full object-contain mix-blend-multiply" /> : <span className="material-icons text-xs text-gray-300">image</span>}
                        </div>
                        <div>
                          <div className="font-black text-black uppercase tracking-tight leading-none mb-1">{item.product.title}</div>
                          <div className="text-[8px] font-mono text-gray-400 uppercase">{item.variant.sku} • {item.variant.option1}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center bg-white border border-black/10 rounded-lg h-7 w-20 mx-auto overflow-hidden">
                        <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity - 1)} className="flex-1 hover:bg-gray-100 text-[10px] font-bold">-</button>
                        <span className="w-6 text-center font-black text-[10px]">{item.quantity}</span>
                        <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity + 1)} className="flex-1 hover:bg-gray-100 text-[10px] font-bold">+</button>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="font-black text-black">${(item.variant.price * item.quantity).toFixed(2)}</div>
                      <button onClick={() => onRemove(item.variant.sku)} className="text-[7px] text-red-500 font-black uppercase mt-1 opacity-0 group-hover:opacity-100 transition-opacity">Eliminar</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="lg:col-span-4">
          <div className="bg-white rounded-[20px] border border-black/5 p-6 shadow-xl">
            <h2 className="text-[8px] font-black text-black uppercase tracking-widest mb-6 border-b border-black/5 pb-2">Resumen Financiero</h2>
            <div className="space-y-3 mb-6">
              <div className="flex justify-between text-[9px] text-gray-400 font-bold uppercase">
                <span>Base Imponible</span>
                <span className="text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-[9px] text-gray-400 font-bold uppercase">
                <span>ITBMS (7%)</span>
                <span className="text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="pt-3 border-t border-black/5 flex justify-between items-baseline">
                <span className="text-[9px] font-black uppercase">Total Neto</span>
                <span className="text-3xl font-black text-black tracking-tighter leading-none">${total.toFixed(2)}</span>
              </div>
            </div>

            <div className="space-y-2.5">
              <button 
                onClick={handleWhatsApp}
                className="w-full h-11 bg-black text-white rounded-full text-[9px] font-black uppercase tracking-widest hover:bg-[#1D1D1F] active:scale-95 transition-all flex items-center justify-center gap-2 shadow-lg"
              >
                <span className="material-icons text-sm">chat</span> Enviar por WhatsApp
              </button>
              <button 
                onClick={handleEmail}
                className="w-full h-11 bg-white border border-black/10 text-black rounded-full text-[9px] font-black uppercase tracking-widest hover:bg-gray-50 active:scale-95 transition-all flex items-center justify-center gap-2"
              >
                <span className="material-icons text-sm">email</span> Enviar por Correo
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

