import React, { useState } from 'react';
import { Product, ProductVariant } from '../types';
import { COLOR_MAP } from '../constants';

interface ProductDetailViewProps {
  product: Product;
  onAddToCart: (p: Product, variantSku: string, quantity: number) => void;
  onBack: () => void;
}

const ProductDetailView: React.FC<ProductDetailViewProps> = ({ product, onAddToCart, onBack }) => {
  const [selectedVariant, setSelectedVariant] = useState<ProductVariant>(product.variants[0]);
  const [quantity, setQuantity] = useState(1);
  const [isAdded, setIsAdded] = useState(false);

  const itemTotal = (selectedVariant.price * quantity).toFixed(2);

  const handleAdd = () => {
    onAddToCart(product, selectedVariant.sku, quantity);
    setIsAdded(true);
    setTimeout(() => setIsAdded(false), 2000);
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8 animate-in fade-in duration-300">
      <nav className="mb-6">
        <button onClick={onBack} className="flex items-center text-xs font-black text-[#86868B] uppercase tracking-[0.3em] hover:text-black">
          <span className="material-icons text-sm mr-2">arrow_back</span> Regresar al Listado
        </button>
      </nav>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 bg-white rounded-[32px] border border-black/5 p-6 md:p-10 shadow-2xl">

        {/* Visualización SKU */}
        <div className="lg:col-span-5 flex items-center justify-center bg-[#F5F5F7] rounded-[24px] p-6 min-h-[300px] md:min-h-[450px]">
          {selectedVariant.image ? (
            <img 
              src={selectedVariant.image} 
              alt={selectedVariant.sku} 
              className="max-w-full max-h-[400px] object-contain mix-blend-multiply transition-transform"
            />
          ) : (
            <div className="flex flex-col items-center text-gray-300">
              <span className="material-icons text-6xl mb-4">inventory_2</span>
              <span className="text-[10px] font-black uppercase tracking-widest">Sin Visual Disponible</span>
            </div>
          )}
        </div>

        {/* Info y Acción */}
        <div className="lg:col-span-7 flex flex-col justify-between">
          <div>
            <header className="mb-8 pb-6 border-b border-black/5">
              <div className="text-[10px] font-black text-link-blue uppercase tracking-widest mb-2">
                {product.category} • {product.type}
              </div>
              <h1 className="text-3xl md:text-4xl font-black text-black tracking-tighter uppercase leading-tight mb-4">
                {product.title}
              </h1>
              <p className="text-sm text-gray-500 font-medium uppercase tracking-tight leading-relaxed">
                {product.description}
              </p>
            </header>

            {/* Modelos y Colores */}
            <div className="mb-10">
              <div className="flex justify-between items-center mb-4">
                <h3 className="text-[11px] font-black text-black uppercase tracking-widest">Variantes de SKU</h3>
                <span className="text-[10px] font-mono font-bold text-gray-400">{selectedVariant.sku}</span>
              </div>
              <div className="flex flex-wrap gap-2">
                {product.variants.map((v) => (
                  <button 
                    key={v.sku}
                    onClick={() => setSelectedVariant(v)}
                    className={`flex items-center gap-3 p-2 px-4 rounded-full border-2 transition-all ${
                      selectedVariant.sku === v.sku 
                        ? 'border-black bg-black text-white shadow-lg' 
                        : 'border-black/5 hover:border-black/20 bg-white text-black'
                    }`}
                  >
                    <div 
                      className="w-4 h-4 rounded-full border border-black/10"
                      style={{ backgroundColor: COLOR_MAP[v.option1] || '#CCC' }}
                    />
                    <span className="text-[10px] font-black uppercase truncate max-w-[120px]">{v.option1}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Bloque de Acción Premium */}
          <div className="bg-[#1D1D1F] rounded-[28px] p-6 text-white shadow-2xl">
            <div className="flex flex-row items-center justify-between gap-6 mb-8">
              <div className="flex-1">
                <div className="text-[10px] font-black text-gray-500 uppercase tracking-widest mb-3">Unidades</div>
                <div className="flex items-center bg-white/10 rounded-2xl border border-white/5 h-14 px-2 relative">
                  <button 
                    onClick={() => setQuantity(q => Math.max(1, q - 1))} 
                    className="w-10 h-10 flex items-center justify-center hover:bg-white/20 rounded-xl text-white active:scale-90 transition-all"
                  >
                    <span className="material-icons text-sm">remove</span>
                  </button>
                  <input 
                    type="number" 
                    className="flex-1 bg-transparent border-none text-center font-black text-lg focus:ring-0 text-white p-0" 
                    value={quantity}
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                  />
                  <button 
                    onClick={() => setQuantity(q => q + 1)} 
                    className="w-10 h-10 flex items-center justify-center hover:bg-white/20 rounded-xl text-white active:scale-90 transition-all"
                  >
                    <span className="material-icons text-sm">add</span>
                  </button>
                </div>
              </div>

              <div className="text-right flex-1 border-l border-white/10 pl-6">
                <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest block mb-2">Total SKU</span>
                <div className="text-3xl font-black tracking-tighter text-white">
                  ${itemTotal}
