              </div>
            </div>

            <button 
              onClick={handleAdd}
              className={`w-full h-14 rounded-2xl font-black text-xs uppercase tracking-[0.3em] transition-all flex items-center justify-center gap-3 ${
                isAdded ? 'bg-accent-green text-white' : 'bg-white text-black hover:bg-gray-100 active:scale-95'
              }`}
            >
              <span className="material-icons text-base">{isAdded ? 'done_all' : 'add_shopping_cart'}</span>
              {isAdded ? 'Añadido Correctamente' : 'Cargar a la Proforma'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

