      text += `${i+1}. *${item.product.title}*${br}   SKU: \`${item.variant.sku}\` | Cant: ${item.quantity}${br}${br}`;
    });
    text += `*MONTO FINAL ESTIMADO: $${total.toFixed(2)}*${br}${br}ID: ${Date.now().toString().slice(-6)}`;
    return text;
