        <div className="lg:col-span-7 flex flex-col justify-between py-4">
          <div>
            <header className="mb-10 pb-8 border-b border-black/5">
              <div className="text-xs font-black text-link-blue uppercase tracking-[0.4em] mb-4">
                {product.category} • {product.type}
              </div>
              <h1 className="text-4xl md:text-6xl font-black text-black tracking-tighter uppercase leading-[0.9] mb-8">
                {product.title}
              </h1>
              <p className="text-lg text-gray-500 font-medium uppercase tracking-tight leading-relaxed max-w-xl">
                {product.description}
              </p>
            </header>

            {/* Modelos y Colores */}
            <div className="mb-12">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-xs font-black text-black uppercase tracking-[0.3em]">Seleccionar Variante</h3>
                <span className="text-xs font-mono font-bold text-gray-400 bg-gray-50 px-3 py-1 rounded-full border">SKU: {selectedVariant.sku}</span>
              </div>
              <div className="flex flex-wrap gap-3">
                {product.variants.map((v) => (
                  <button 
                    key={v.sku}
                    onClick={() => setSelectedVariant(v)}
                    className={`flex items-center gap-4 p-3 px-6 rounded-full border-2 transition-all ${
                      selectedVariant.sku === v.sku 
                        ? 'border-black bg-black text-white shadow-xl scale-105' 
                        : 'border-black/5 hover:border-black/20 bg-white text-black'
                    }`}
                  >
                    <div 
                      className="w-5 h-5 rounded-full border border-black/10 shadow-inner"
                      style={{ backgroundColor: COLOR_MAP[v.option1] || '#CCC' }}
                    />
                    <span className="text-xs font-black uppercase tracking-widest">{v.option1}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Bloque de Acción Premium */}
          <div className="bg-[#1D1D1F] rounded-[40px] p-8 md:p-12 text-white shadow-2xl">
            <div className="flex flex-col md:flex-row items-center justify-between gap-10 mb-10">
              <div className="w-full md:w-auto flex-1">
                <div className="text-xs font-black text-gray-500 uppercase tracking-[0.4em] mb-4">Cantidad Unidades</div>
                <div className="flex items-center bg-white/5 rounded-2xl border border-white/10 h-16 px-2">
                  <button 
                    onClick={() => setQuantity(q => Math.max(1, q - 1))} 
                    className="w-12 h-12 flex items-center justify-center hover:bg-white/10 rounded-xl text-white transition-all active:scale-90"
                  >
                    <span className="material-icons text-xl">remove</span>
                  </button>
                  <input 
                    type="number" 
                    className="flex-1 bg-transparent border-none text-center font-black text-2xl focus:ring-0 text-white p-0" 
                    value={quantity}
                    onChange={(e) => setQuantity(Math.max(1, parseInt(e.target.value) || 1))}
                  />
                  <button 
                    onClick={() => setQuantity(q => q + 1)} 
                    className="w-12 h-12 flex items-center justify-center hover:bg-white/10 rounded-xl text-white transition-all active:scale-90"
                  >
                    <span className="material-icons text-xl">add</span>
                  </button>
                </div>
              </div>

              <div className="text-right w-full md:w-auto flex-1 border-t md:border-t-0 md:border-l border-white/10 pt-8 md:pt-0 md:pl-10">
                <span className="text-xs font-black text-gray-500 uppercase tracking-[0.4em] block mb-3">Total Línea</span>
                <div className="text-5xl md:text-6xl font-black tracking-tighter text-white leading-none">
                  ${itemTotal}
                </div>
              </div>
            </div>

            <button 
              onClick={handleAdd}
              className={`w-full h-20 rounded-[28px] font-black text-sm uppercase tracking-[0.4em] transition-all flex items-center justify-center gap-4 ${
                isAdded ? 'bg-accent-green text-white shadow-2xl' : 'bg-white text-black hover:bg-gray-100 active:scale-95 shadow-xl'
              }`}
            >
              <span className="material-icons text-xl">{isAdded ? 'done_all' : 'add_shopping_cart'}</span>
              {isAdded ? 'Añadido a la Proforma' : 'Cargar Pedido'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

