import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const buildOrderText = () => {
    const br = "\n";
    let text = `📦 *ORDEN B2B CUBITT PANAMA*${br}${br}`;
    cart.forEach((item, i) => {
      text += `${i+1}. *${item.product.title}*${br}   SKU: \`${item.variant.sku}\` | Cant: ${item.quantity}${br}${br}`;
    });
    text += `*MONTO FINAL ESTIMADO: $${total.toFixed(2)}*${br}${br}ID: ${Date.now().toString().slice(-6)}`;
    return text;
  };

  const handleWhatsApp = () => {
    window.open(`https://wa.me/50761541129?text=${encodeURIComponent(buildOrderText())}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("Solicitud de Orden Mayorista - Cubitt Panama");
    const body = encodeURIComponent(buildOrderText());
    window.location.href = `mailto:ventas@cubitt.com?subject=${subject}&body=${body}`;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-xl mx-auto px-4 py-32 text-center">
        <span className="material-icons text-8xl text-gray-200 mb-10">receipt_long</span>
        <h2 className="text-2xl font-black uppercase tracking-[0.4em] mb-12">Proforma Vacía</h2>
        <button onClick={onBack} className="bg-black text-white px-12 py-5 rounded-full text-sm font-black uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all">
          Ver Inventario
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-12 animate-in fade-in duration-400">
      <div className="flex flex-col md:flex-row justify-between items-end mb-16 gap-10">
        <div>
          <button onClick={onBack} className="text-xs font-black text-gray-400 uppercase tracking-[0.5em] mb-6 flex items-center gap-3 hover:text-black">
            <span className="material-icons text-base">west</span> Volver al Catálogo
          </button>
          <h1 className="text-5xl md:text-7xl font-black text-black uppercase tracking-tighter">Tu Pedido</h1>
        </div>
        <div className="bg-black text-white px-10 py-6 rounded-[32px] flex items-center gap-8 shadow-2xl">
          <div className="text-right">
            <div className="text-xs font-black uppercase tracking-widest opacity-40">Total Líneas</div>
            <div className="text-3xl font-black leading-none">{cart.length} SKUs</div>
          </div>
          <div className="w-px h-12 bg-white/20" />
          <span className="material-icons text-4xl">fact_check</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[48px] border border-black/5 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-[#F5F5F7] text-xs font-black text-gray-400 uppercase tracking-widest border-b border-black/5">
                <tr>
                  <th className="px-10 py-8">Producto / SKU</th>
                  <th className="px-10 py-8 text-center w-40">Cant</th>
                  <th className="px-10 py-8 text-right">Subtotal</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/5">
                {cart.map(item => (
                  <tr key={item.variant.sku} className="group hover:bg-[#F5F5F7]/30 transition-colors">
                    <td className="px-10 py-10">
                      <div className="flex items-center gap-8">
                        <div className="w-20 h-20 bg-[#F5F5F7] rounded-3xl p-3 border border-black/5 shrink-0 flex items-center justify-center">
                          {item.variant.image ? <img src={item.variant.image} className="max-h-full object-contain mix-blend-multiply" /> : <span className="material-icons text-gray-300">image</span>}
                        </div>
                        <div>
                          <div className="text-xl font-black text-black uppercase tracking-tight leading-none mb-3">{item.product.title}</div>
                          <div className="flex items-center gap-3">
                            <span className="text-xs font-bold text-gray-500 uppercase">{item.variant.option1}</span>
                            <span className="text-gray-300">/</span>
                            <span className="text-xs font-mono text-black font-black bg-black/5 px-2 py-0.5 rounded uppercase">{item.variant.sku}</span>
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-10 py-10">
                      <div className="flex items-center bg-white border border-black/10 rounded-2xl h-12 w-28 mx-auto overflow-hidden shadow-inner px-2">
                        <button onClick={() => onUpdateQuantity(item.variant.sku, item.quantity - 1)} className="flex-1 hover:bg-gray-100 font-bold text-lg">-</button>
