                      </div>
                    </td>
                    <td className="px-10 py-10 text-right">
                      <div className="text-2xl font-black text-black tracking-tighter">${(item.variant.price * item.quantity).toFixed(2)}</div>
                      <button onClick={() => onRemove(item.variant.sku)} className="text-[10px] text-red-500 font-black uppercase mt-3 opacity-0 group-hover:opacity-100 transition-opacity underline decoration-2">Quitar SKU</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="lg:col-span-4">
          <div className="bg-white rounded-[48px] border border-black/5 p-12 sticky top-24 shadow-2xl shadow-black/5">
            <h2 className="text-xs font-black text-black uppercase tracking-[0.4em] mb-12 border-b border-black/5 pb-6 text-center">Consolidado B2B</h2>

            <div className="space-y-8 mb-12">
              <div className="flex justify-between text-sm font-black uppercase tracking-widest text-gray-400">
                <span>Neto</span>
                <span className="text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-sm font-black uppercase tracking-widest text-gray-400">
                <span>Impuesto (7%)</span>
                <span className="text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="pt-10 border-t border-black/5 text-right">
                <div className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Total Proforma</div>
                <div className="text-6xl font-black text-black tracking-tighter leading-none">${total.toFixed(2)}</div>
              </div>
            </div>

            <div className="space-y-5">
              <button 
                onClick={handleWhatsApp}
                className="w-full h-20 bg-black text-white rounded-[32px] text-xs font-black uppercase tracking-[0.3em] hover:bg-[#1D1D1F] active:scale-[0.98] transition-all flex items-center justify-center gap-5 shadow-2xl group"
              >
                <span className="material-icons text-2xl group-hover:scale-110 transition-transform">chat</span>
                WhatsApp Ventas
              </button>

              <button 
                onClick={handleEmail}
                className="w-full h-20 bg-[#F5F5F7] text-black border border-black/5 rounded-[32px] text-xs font-black uppercase tracking-[0.3em] hover:bg-[#EBEBEB] active:scale-[0.98] transition-all flex items-center justify-center gap-5 group"
              >
                <span className="material-icons text-2xl group-hover:scale-110 transition-transform">alternate_email</span>
                Correo Oficial
              </button>
            </div>

            <p className="mt-10 text-[10px] text-center text-gray-400 font-bold uppercase tracking-widest leading-relaxed">
              * Precios netos por volumen. Cubitt Panama se reserva el derecho de validación de proforma.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

