import React from 'react';
import { CartItem } from '../types';

interface ReviewOrderViewProps {
  cart: CartItem[];
  onUpdateQuantity: (sku: string, qty: number) => void;
  onRemove: (sku: string) => void;
  onBack: () => void;
  onConfirm: () => void;
}

const ReviewOrderView: React.FC<ReviewOrderViewProps> = ({ cart, onUpdateQuantity, onRemove, onBack, onConfirm }) => {
  const subtotal = cart.reduce((acc, curr) => acc + (curr.variant.price * curr.quantity), 0);
  const tax = subtotal * 0.07;
  const total = subtotal + tax;

  const buildOrderText = () => {
    const br = "\n";
    let text = `📦 *ORDEN B2B CUBITT PANAMA*${br}${br}`;
    cart.forEach((item, i) => {
      text += `${i+1}. *${item.product.title}*${br}   SKU: \`${item.variant.sku}\` | Cant: ${item.quantity}${br}${br}`;
    });
    text += `*TOTAL FINAL: $${total.toFixed(2)}*${br}${br}ID SOLICITUD: ${Date.now().toString().slice(-6)}`;
    return text;
  };

  const handleWhatsApp = () => {
    window.open(`https://wa.me/50761541129?text=${encodeURIComponent(buildOrderText())}`, '_blank');
    onConfirm();
  };

  const handleEmail = () => {
    const subject = encodeURIComponent("Orden Mayorista Cubitt - " + new Date().toLocaleDateString());
    const body = encodeURIComponent(buildOrderText());
    window.location.href = `mailto:ventas@cubitt.com?subject=${subject}&body=${body}`;
    onConfirm();
  };

  if (cart.length === 0) {
    return (
      <div className="max-w-2xl mx-auto px-4 py-40 text-center">
        <span className="material-icons text-[120px] text-gray-200 mb-12">receipt_long</span>
        <h2 className="text-3xl font-black uppercase tracking-[0.5em] mb-16">Sin SKUs Cargados</h2>
        <button onClick={onBack} className="bg-black text-white px-16 py-6 rounded-full text-base font-black uppercase tracking-[0.2em] shadow-2xl hover:scale-105 active:scale-95 transition-all">
          Explorar Inventario
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-16 md:py-24 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row justify-between items-end mb-20 gap-12">
        <div>
          <button onClick={onBack} className="text-sm font-black text-gray-400 uppercase tracking-[0.6em] mb-8 flex items-center gap-4 hover:text-black group">
            <span className="material-icons text-xl group-hover:-translate-x-1 transition-transform">west</span> Regresar
          </button>
          <h1 className="text-6xl md:text-8xl font-black text-black uppercase tracking-tighter leading-none">Mi Proforma</h1>
        </div>
        <div className="bg-black text-white px-12 py-8 rounded-[40px] flex items-center gap-10 shadow-2xl">
          <div className="text-right">
            <div className="text-xs font-black uppercase tracking-widest opacity-40 mb-2">Líneas SKU</div>
            <div className="text-4xl font-black leading-none">{cart.length}</div>
          </div>
          <div className="w-px h-16 bg-white/20" />
          <span className="material-icons text-5xl">inventory</span>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-16">
        <div className="lg:col-span-8">
          <div className="bg-white rounded-[56px] border border-black/5 overflow-hidden shadow-sm">
            <table className="w-full text-left">
              <thead className="bg-[#F5F5F7] text-xs font-black text-gray-400 uppercase tracking-[0.4em] border-b border-black/5">
                <tr>
                  <th className="px-12 py-10">Artículos / SKU Técnico</th>
                  <th className="px-12 py-10 text-center w-48">Cant</th>
                  <th className="px-12 py-10 text-right">Monto</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-black/5">
                {cart.map(item => (
                  <tr key={item.variant.sku} className="group hover:bg-[#F5F5F7]/40 transition-colors">
                    <td className="px-12 py-12">
                      <div className="flex items-center gap-10">
                        <div className="w-24 h-24 bg-[#F5F5F7] rounded-[32px] p-4 border border-black/5 shrink-0 flex items-center justify-center shadow-inner">
                          {item.variant.image ? <img src={item.variant.image} className="max-h-full object-contain mix-blend-multiply" /> : <span className="material-icons text-3xl text-gray-300">image</span>}
                        </div>
                        <div>
