            <div className="space-y-10 mb-16">
              <div className="flex justify-between text-base font-black uppercase tracking-widest text-gray-400">
                <span>Neto</span>
                <span className="text-black">${subtotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-base font-black uppercase tracking-widest text-gray-400">
                <span>Tax ITBMS (7%)</span>
                <span className="text-black">${tax.toFixed(2)}</span>
              </div>
              <div className="pt-12 border-t border-black/5 text-right">
                <div className="text-sm font-black text-gray-400 uppercase tracking-[0.5em] mb-6">Total Solicitado</div>
                <div className="text-7xl md:text-8xl font-black text-black tracking-tighter leading-[0.8]">${total.toFixed(2)}</div>
              </div>
            </div>

            <div className="space-y-6">
              <button 
                onClick={handleWhatsApp}
                className="w-full h-24 bg-black text-white rounded-[32px] text-sm font-black uppercase tracking-[0.5em] hover:bg-[#1D1D1F] active:scale-[0.98] transition-all flex items-center justify-center gap-6 shadow-2xl group"
