                <span className="material-icons text-3xl group-hover:scale-110 transition-transform">chat</span>
                Confirmar WhatsApp
              </button>

              <button 
                onClick={handleEmail}
                className="w-full h-24 bg-[#F5F5F7] text-black border border-black/5 rounded-[32px] text-sm font-black uppercase tracking-[0.5em] hover:bg-[#EBEBEB] active:scale-[0.98] transition-all flex items-center justify-center gap-6 group"
              >
                <span className="material-icons text-3xl group-hover:scale-110 transition-transform">mail</span>
