                  >
                    <span className="material-icons text-3xl">add</span>
                  </button>
                </div>
              </div>

              <div className="text-right w-full md:w-auto flex-1 border-t md:border-t-0 md:border-l border-white/10 pt-12 md:pt-0 md:pl-16">
                <span className="text-sm font-black text-gray-500 uppercase tracking-[0.5em] block mb-6">Monto Estimado</span>
                <div className="text-7xl md:text-8xl font-black tracking-tighter text-white leading-none">
                  ${itemTotal}
                </div>
              </div>
            </div>

            <button 
              onClick={handleAdd}
              className={`w-full h-28 rounded-[40px] font-black text-xl uppercase tracking-[0.6em] transition-all flex items-center justify-center gap-8 ${
                isAdded ? 'bg-accent-green text-white shadow-2xl scale-[1.02]' : 'bg-white text-black hover:bg-gray-100 active:scale-95 shadow-xl'
              }`}
            >
              <span className="material-icons text-3xl">{isAdded ? 'done_all' : 'add_shopping_cart'}</span>
              {isAdded ? 'Añadido Correctamente' : 'Cargar a Proforma'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetailView;

